import { Book } from "@/lib/types";

export const mark: Book = {
  id: "mark",
  name: "Markus",
  shortName: "Mk",
  testament: "new",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "**Anfang des Evangeliums Jesu Christi, *des Sohnes Gottes*;", heading: "Johannes der Täufer", footnotes: ["℘ Mt 3,1-12; Lk 3,1-18; (Joh 1,19-28)", "o. Anfang des Evangeliums Jesu Christi, des Sohnes Gottes: 2 Wie in dem Propheten Jesaja geschrieben steht: ». . .«, 4 so geschah es: Johannes taufte in der Wüste und predigte die Taufe der Buße", "in einigen Handschr. nicht enthalten", "in einigen Handschr. nicht enthalten\n℘ Röm 1,4 ⇨Esyn: Synopse Nr. 1"] },
      { number: 2, text: "wie in dem Propheten Jesaja geschrieben steht: »Siehe, ich sende meinen Boten vor deinem Angesicht her, der deinen Weg bereiten wird.«*", footnotes: ["℘ Mal 3,1; Mt 11,10; Lk 7,27 ⇨Esyn: Synopse Nr. 107"] },
      { number: 3, text: "»Stimme eines Rufenden in der Wüste: Bereitet den Weg des Herrn, macht seine Pfade gerade!«*", footnotes: ["℘ Jes 40,3"] },
      { number: 4, text: "Johannes trat auf und taufte in der Wüste und predigte die Taufe der Buße* zur Vergebung der Sünden*.", footnotes: ["o. Anfang des Evangeliums Jesu Christi, des Sohnes Gottes: 2 Wie in dem Propheten Jesaja geschrieben steht: ». . .«, 4 so geschah es: Johannes taufte in der Wüste und predigte die Taufe der Buße", "℘ Apg 13,24 ⇨Esyn: Synopse Nr. 32"] },
      { number: 5, text: "Und es ging zu ihm hinaus das ganze jüdische Land und alle Einwohner Jerusalems, und sie wurden im Jordanfluss von ihm getauft*, indem sie ihre Sünden bekannten.", footnotes: ["℘ Joh 3,23"] },
      { number: 6, text: "Und Johannes war mit Kamelhaaren und einem ledernen Gürtel um seine Lende bekleidet*; und er aß Heuschrecken und wilden Honig.", footnotes: ["℘ 2Kö 1,8"] },
      { number: 7, text: "Und er predigte und sagte: Nach mir kommt der, der stärker ist als ich; ich bin nicht würdig, <ihm> gebückt den Riemen seiner Sandalen zu lösen*.", footnotes: ["℘ Apg 13,25 ⇨Esyn: Synopse Nr. 16"] },
      { number: 8, text: "Ich habe euch mit* Wasser getauft, er aber wird euch mit* Heiligem Geist taufen*.", footnotes: ["o. in", "o. in", "℘ Apg 1,5"] },
      { number: 9, text: "*Und es geschah in jenen Tagen: Jesus kam von Nazareth in Galiläa* und wurde von Johannes im Jordan getauft.", heading: "Die Taufe und Versuchung Jesu", footnotes: ["℘ Mt 3,13-17; Lk 3,21.22; (Joh 1,29-34)", "℘ Mt 2,22.23 ⇨Esyn: Synopse Nr. 18"] },
      { number: 10, text: "Und sobald er aus dem Wasser heraufstieg, sah er die Himmel sich teilen und den Geist wie eine Taube auf ihn herabfahren." },
      { number: 11, text: "Und eine Stimme kam aus den Himmeln*: Du bist mein geliebter Sohn*, an dir habe ich Wohlgefallen gefunden*.", footnotes: ["℘ Joh 12,28", "℘ Eph 1,6", "℘ Kap. 9,7 ⇨Esyn: Synopse Nr. 302"] },
      { number: 12, text: "*Und sogleich treibt ihn der Geist in die Wüste hinaus. *", footnotes: ["℘ Mt 4,1-11; Lk 4,1-13", "℘ ⇨Esyn: Synopse Nr. 20"] },
      { number: 13, text: "Und er war vierzig Tage in der Wüste und wurde von dem Satan versucht; und er war unter den wilden Tieren, und die Engel dienten ihm*.", footnotes: ["℘ Lk 22,43; Jes 42,1"] },
      { number: 14, text: "*Und nachdem Johannes überliefert war*, kam Jesus nach Galiläa und predigte das Evangelium Gottes*", heading: "Bußpredigt in Galiläa — Die ersten Jünger", footnotes: ["℘ Mt 4,12-22; Lk 4,14.15; 5,1-11", "℘ Kap. 6,17; Joh 3,24", "℘ Lk 8,1; Hebr 2,3 ⇨Esyn: Synopse Nr. 32"] },
      { number: 15, text: "und sprach: Die Zeit ist erfüllt*, und das Reich* Gottes ist nahe gekommen. Tut Buße und glaubt an das Evangelium*!", footnotes: ["℘ Gal 4,4", "o. die Königsherrschaft", "℘ Mt 3,2"] },
      { number: 16, text: "Und als er am See von Galiläa entlangging, sah er Simon und Andreas, Simons Bruder, im See die Netze auswerfen, denn sie waren Fischer. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 41"] },
      { number: 17, text: "Und Jesus sprach zu ihnen: Kommt mir nach*, und ich werde euch zu Menschenfischern machen*!", footnotes: ["℘ Kap. 2,14", "w. ich werde machen, dass ihr Menschenfischer werdet"] },
      { number: 18, text: "Und sogleich verließen sie die Netze und folgten ihm nach*.", footnotes: ["℘ Kap. 10,28"] },
      { number: 19, text: "Und als er ein wenig weiterging, sah er Jakobus, den <Sohn> des Zebedäus, und seinen Bruder Johannes, auch sie im Boot, wie sie die Netze ausbesserten;" },
      { number: 20, text: "und sogleich rief er sie. Und sie ließen ihren Vater Zebedäus mit den Tagelöhnern im Boot und gingen weg, ihm nach*.", footnotes: ["℘ Kap. 10,28"] },
      { number: 21, text: "*Und sie gehen nach Kapernaum* hinein. Und sogleich ging er am Sabbat in die Synagoge* und lehrte*.", heading: "Heilung eines Besessenen", footnotes: ["℘ Lk 4,31-37", "℘ Kap. 2,1; Mt 4,13", "Versammlungsstätte der jüdischen Gemeinde; s. a. Anm. zu Mt 4,23", "℘ Mt 4,23 ⇨Esyn: Synopse Nr. 35"] },
      { number: 22, text: "Und sie erstaunten sehr über seine Lehre; denn er lehrte sie wie einer, der Vollmacht hat, und nicht wie die Schriftgelehrten*.", footnotes: ["℘ Mt 7,28.29"] },
      { number: 23, text: "Und sogleich war in ihrer Synagoge ein Mensch mit einem unreinen Geist*; und er schrie auf*", footnotes: ["℘ Kap. 5,8", "℘ Mt 8,29 ⇨Esyn: Synopse Nr. 36"] },
      { number: 24, text: "und sagte: Was haben wir mit dir zu schaffen, Jesus, Nazarener*? Bist du gekommen, uns zu verderben? Ich kenne dich, wer du bist: der Heilige Gottes*.", footnotes: ["℘ Mt 2,23", "℘ Kap. 3,11; 5,7; Joh 6,69"] },
      { number: 25, text: "Und Jesus bedrohte ihn und sprach: Verstumme* und fahre aus von ihm*!", footnotes: ["℘ V. 34; Kap. 3,12", "℘ Kap. 9,25.26; Apg 16,18"] },
      { number: 26, text: "Und der unreine Geist zerrte ihn und rief mit lauter Stimme und fuhr von ihm aus*.", footnotes: ["℘ Kap. 9,25.26; Apg 16,18"] },
      { number: 27, text: "Und sie entsetzten sich alle, so dass sie sich untereinander befragten und sagten: Was ist dies? Eine neue Lehre mit Vollmacht? Und den unreinen Geistern gebietet er, und sie gehorchen ihm*.", footnotes: ["℘ Kap. 4,41"] },
      { number: 28, text: "Und die Kunde von ihm ging sogleich hinaus überall in die ganze Umgebung Galiläas." },
      { number: 29, text: "*Und sobald sie aus der Synagoge hinausgingen, kamen sie mit Jakobus und Johannes in das Haus Simons und Andreas'. *", heading: "Heilung der Schwiegermutter des Petrus", footnotes: ["℘ Mt 8,14.15; Lk 4,38.39", "℘ ⇨Esyn: Synopse Nr. 37"] },
      { number: 30, text: "Die Schwiegermutter Simons* aber lag fieberkrank danieder; und sofort sagen sie ihm von ihr.", footnotes: ["℘ 1Kor 9,5"] },
      { number: 31, text: "Und er trat hinzu, ergriff ihre Hand* und richtete sie auf; und das Fieber verließ sie, und sie diente ihnen*.", footnotes: ["℘ Kap. 5,41; 9,27", "℘ Lk 8,2.3"] },
      { number: 32, text: "*Als es aber Abend geworden war und die Sonne unterging, brachten sie alle Leidenden und Besessenen zu ihm; *", heading: "Heilungen und Predigt", footnotes: ["℘ Mt 4,23-25; 8,16.17; Lk 4,40-44", "℘ ⇨Esyn: Synopse Nr. 38"] },
      { number: 33, text: "und die ganze Stadt war an der Tür versammelt." },
      { number: 34, text: "Und er heilte viele an mancherlei Krankheiten Leidende, und er trieb viele Dämonen aus* und ließ die Dämonen nicht reden, weil sie ihn kannten*.", footnotes: ["℘ Apg 10,38", "℘ V. 25.43; Mt 8,4 ⇨Esyn: Synopse Nr. 113"] },
      { number: 35, text: "Und frühmorgens, als es noch sehr dunkel war, stand er auf und ging hinaus und ging fort an einen einsamen Ort und betete dort*.", footnotes: ["℘ Kap. 6,46; Mt 14,23 ⇨Esyn: Synopse Nr. 39"] },
      { number: 36, text: "Und Simon und die, die mit ihm waren*, eilten ihm nach;", footnotes: ["℘ Lk 8,45"] },
      { number: 37, text: "und sie fanden ihn und sagen zu ihm: Alle suchen dich." },
      { number: 38, text: "Und er spricht zu ihnen: Lasst uns anderswohin in die benachbarten Marktflecken gehen, damit ich auch dort predige; denn dazu bin ich ausgegangen." },
      { number: 39, text: "Und er ging und predigte in ihren Synagogen in ganz Galiläa* und trieb die Dämonen aus*.", footnotes: ["℘ Apg 10,38", "℘ Lk 4,15 ⇨Esyn: Synopse Nr. 40"] },
      { number: 40, text: "*Und es kommt ein Aussätziger* zu ihm, bittet ihn und kniet nieder und spricht zu ihm: Wenn du willst, kannst du mich reinigen. *", heading: "Heilung eines Aussätzigen", footnotes: ["℘ Mt 8,1-4; Lk 5,12-16", "»Aussatz« umfasste in biblischer Zeit mehrere Hautkrankheiten; s. auch Anm. zu Mt 8,2.", "℘ ⇨Esyn: Synopse Nr. 42"] },
      { number: 41, text: "Und er war innerlich bewegt* und streckte seine Hand aus, rührte <ihn> an und spricht zu ihm: Ich will. Sei gereinigt!", footnotes: ["℘ Kap. 6,34; 8,2; Mt 9,36; Lk 10,33"] },
      { number: 42, text: "Und sogleich wich der Aussatz von ihm, und er war gereinigt*.", footnotes: ["℘ Ps 33,9"] },
      { number: 43, text: "Und er bedrohte ihn und schickte ihn sogleich fort*", footnotes: ["℘ V. 25"] },
      { number: 44, text: "und spricht zu ihm: Sieh zu, sage niemand etwas*! Sondern geh hin, zeige dich dem Priester, und opfere für deine Reinigung, was Mose geboten hat, ihnen zu einem Zeugnis*!", footnotes: ["℘ Kap. 3,12; 5,43; 7,36; 8,26", "℘ 3Mo 14,1-20"] },
      { number: 45, text: "Der aber ging weg und fing an, die Sache* eifrig zu verkünden und auszubreiten*, so dass er nicht mehr öffentlich in eine Stadt gehen konnte; sondern er war draußen an einsamen Orten, und sie kamen von allen Seiten zu ihm.", footnotes: ["o. das Wort", "℘ Kap. 5,20; 7,36; Mt 9,31"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "*Und nach einigen Tagen ging er wieder nach Kapernaum* hinein, und es wurde bekannt, dass er im Hause sei.", heading: "Heilung eines Gelähmten", footnotes: ["℘ Mt 9,1-8; Lk 5,17-26", "℘ Kap. 1,21 ⇨Esyn: Synopse Nr. 43"] },
      { number: 2, text: "Und es versammelten sich viele, so dass sie keinen Platz mehr hatten, nicht einmal vor der Tür; und er sagte ihnen das Wort*.", footnotes: ["℘ Lk 5,1"] },
      { number: 3, text: "Und sie kommen zu ihm und bringen einen Gelähmten, von vieren getragen." },
      { number: 4, text: "Und da sie <ihn> wegen der Volksmenge nicht zu ihm bringen konnten, deckten sie das Dach ab, wo er war; und als sie es aufgebrochen hatten, lassen sie das Bett hinab, auf dem der Gelähmte lag." },
      { number: 5, text: "Und als Jesus ihren Glauben sah, spricht er zu dem Gelähmten: Kind, deine Sünden sind* vergeben*.", footnotes: ["w. werden (Zeitform Gegenwart)", "℘ Lk 7,48"] },
      { number: 6, text: "Es saßen dort aber einige von den Schriftgelehrten und überlegten in ihren Herzen:" },
      { number: 7, text: "Was redet dieser so? Er lästert*. Wer kann Sünden vergeben außer einem, Gott*?", footnotes: ["℘ Mt 26,65", "℘ Jes 43,25; 44,22"] },
      { number: 8, text: "Und sogleich erkannte Jesus in seinem Geist, dass sie so bei sich überlegten, und spricht zu ihnen: Was überlegt ihr dies in euren Herzen*?", footnotes: ["℘ Mt 12,25"] },
      { number: 9, text: "Was ist leichter? Zu dem Gelähmten zu sagen: Deine Sünden sind* vergeben, oder zu sagen: Steh auf und nimm dein Bett auf und geh umher?", footnotes: ["w. werden (Zeitform Gegenwart)"] },
      { number: 10, text: "Damit ihr aber wisst, dass der Sohn des Menschen Vollmacht hat, auf der Erde Sünden zu vergeben — spricht er zu dem Gelähmten:" },
      { number: 11, text: "Ich sage dir, steh auf, nimm dein Bett auf und geh in dein Haus*!", footnotes: ["℘ Joh 5,8"] },
      { number: 12, text: "Und er stand auf, nahm sogleich das Bett auf und ging vor allen hinaus, so dass alle außer sich gerieten und Gott verherrlichten* und sagten: Niemals haben wir so etwas gesehen!", footnotes: ["℘ Lk 7,16"] },
      { number: 13, text: "*Und er ging wieder hinaus an den See, und die ganze Volksmenge kam zu ihm, und er lehrte sie. *", heading: "Berufung des Levi", footnotes: ["℘ Mt 9,9-13; Lk 5,27-32", "℘ ⇨Esyn: Synopse Nr. 44"] },
      { number: 14, text: "Und als er vorüberging, sah er Levi, den <Sohn> des Alphäus, am Zollhaus sitzen. Und er spricht zu ihm: Folge mir nach*! Und er stand auf und folgte ihm nach*.", footnotes: ["℘ Kap. 1,17", "℘ Kap. 1,18.20"] },
      { number: 15, text: "Und es geschieht, dass er in seinem Hause zu Tisch lag, und viele Zöllner und Sünder lagen mit Jesus und seinen Jüngern zu Tisch, denn es waren viele, und sie folgten ihm nach*.", footnotes: ["℘ Lk 15,1.2"] },
      { number: 16, text: "Und als die Schriftgelehrten der Pharisäer* ihn mit den Sündern und Zöllnern essen sahen, sagten sie zu seinen Jüngern: Mit den Zöllnern und Sündern isst er*?", footnotes: ["religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; s. a. Anm. zu Mt 3,7", "℘ Lk 15,1.2"] },
      { number: 17, text: "Und Jesus hörte es und spricht zu ihnen: Nicht die Starken brauchen einen Arzt, sondern die Kranken. Ich bin nicht gekommen, Gerechte zu rufen, sondern Sünder*.", footnotes: ["℘ Lk 19,10"] },
      { number: 18, text: "*Und die Jünger des Johannes und die Pharisäer* fasteten; und sie kommen und sagen zu ihm: Warum fasten die Jünger des Johannes und die Jünger der Pharisäer, deine Jünger aber fasten nicht? *", heading: "Die Frage nach dem Fasten", footnotes: ["℘ Mt 9,14-17; Lk 5,33-39", "religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; s. a. Anm. zu Mt 3,7", "℘ ⇨Esyn: Synopse Nr. 45"] },
      { number: 19, text: "Und Jesus sprach zu ihnen: Können etwa die Hochzeitsgäste* fasten, während der Bräutigam bei ihnen ist? Solange sie den Bräutigam bei sich haben, können sie nicht fasten*.", footnotes: ["w. Söhne des Brautgemachs; d. h. der dem Bräutigam am nächsten stehende, unentbehrliche Teil der Hochzeitsgäste", "℘ Joh 3,29"] },
      { number: 20, text: "Es werden aber Tage kommen, da der Bräutigam von ihnen weggenommen sein wird, und dann, an jenem Tag, werden sie fasten*.", footnotes: ["℘ Kap. 16,10; Joh 16,20"] },
      { number: 21, text: "Niemand näht einen Flicken von neuem Tuch auf ein altes Gewand; sonst reißt das Eingesetzte von ihm ab, das Neue vom Alten, und ein schlimmerer Riss entsteht." },
      { number: 22, text: "Auch füllt niemand neuen Wein in alte Schläuche; sonst wird der Wein die Schläuche zerreißen, und der Wein und die Schläuche verderben; sondern neuen Wein <füllt man> in neue Schläuche." },
      { number: 23, text: "*Und es geschah, dass er am Sabbat durch die Saaten ging; und seine Jünger fingen an, im Gehen die Ähren abzupflücken. *", heading: "Die Sabbatfrage", footnotes: ["℘ Mt 12,1-14; Lk 6,1-11", "℘ ⇨Esyn: Synopse Nr. 46"] },
      { number: 24, text: "Und die Pharisäer* sagten zu ihm: Sieh, was tun sie am Sabbat, das nicht erlaubt ist?", footnotes: ["religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; s. a. Anm. zu Mt 3,7"] },
      { number: 25, text: "Und er spricht zu ihnen: Habt ihr nie gelesen, was David tat, als er Mangel hatte und als ihn und die, die bei ihm waren, hungerte?" },
      { number: 26, text: "Wie er in das Haus Gottes ging zur Zeit Abjatars, des Hohenpriesters, und die Schaubrote* aß, die außer den Priestern niemand essen darf*, und auch denen gab, die bei ihm waren*?", footnotes: ["vgl. 2Mo 25,30", "℘ 3Mo 24,9", "℘ 1Sam 21,7"] },
      { number: 27, text: "Und er sprach zu ihnen: Der Sabbat ist um des Menschen willen geschaffen worden und nicht der Mensch um des Sabbats willen*;", footnotes: ["℘ 5Mo 5,14"] },
      { number: 28, text: "somit ist der Sohn des Menschen Herr auch des Sabbats." },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und er ging wieder in die Synagoge; und es war dort ein Mensch, der eine verdorrte Hand hatte. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 47"] },
      { number: 2, text: "Und sie lauerten auf ihn, ob er ihn am Sabbat heilen würde, damit sie ihn anklagen könnten*.", footnotes: ["℘ Kap. 8,11; 10,2; 12,13; Lk 14,1"] },
      { number: 3, text: "Und er spricht zu dem Menschen, der die verdorrte Hand hatte: Steh auf <und tritt> in die Mitte!" },
      { number: 4, text: "Und er spricht zu ihnen: Ist es erlaubt, am Sabbat Gutes zu tun oder Böses zu tun, das Leben zu retten oder zu töten*? Sie aber schwiegen*.", footnotes: ["℘ Lk 13,16", "℘ Lk 14,3.4"] },
      { number: 5, text: "Und er blickte auf sie umher mit Zorn*, betrübt über die Verhärtung ihres Herzens, und spricht zu dem Menschen: Strecke die Hand aus! Und er streckte sie aus, und seine Hand wurde wiederhergestellt.", footnotes: ["℘ Ps 119,53"] },
      { number: 6, text: "Und die Pharisäer* gingen hinaus und hielten mit den Herodianern* sofort Rat gegen ihn, wie sie ihn umbringen könnten*.", footnotes: ["religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; s. a. Anm. zu Mt 3,7", "Anhänger des Herodes Antipas; vgl. Anm. zu Mt 14,1\n℘ Kap. 12,13", "℘ Joh 5,16.18"] },
      { number: 7, text: "*Und Jesus ging mit seinen Jüngern weg an den See; und es folgte eine große Menge von Galiläa und von Judäa *", heading: "Krankenheilungen am See Genezareth", footnotes: ["℘ Mt 12,15-21; Lk 6,17-19", "℘ ⇨Esyn: Synopse Nr. 48"] },
      { number: 8, text: "und von Jerusalem und von Idumäa und <von> jenseits des Jordan und <von der Gegend> rings um Tyrus und Sidon, eine große Menge; da sie hörten, wie viel er tat, kamen sie zu ihm*.", footnotes: ["℘ Mt 4,25; 15,22"] },
      { number: 9, text: "Und er sagte seinen Jüngern, dass ihm wegen der Volksmenge ein Boot bereitgehalten werden sollte, damit sie ihn nicht drängten*.", footnotes: ["℘ Kap. 4,1; 5,24.31; Mt 13,1.2"] },
      { number: 10, text: "Denn er heilte viele, so dass alle, die Leiden hatten, sich auf ihn stürzten, um ihn anzurühren*.", footnotes: ["℘ Kap. 5,27.28; 6,55.56"] },
      { number: 11, text: "Und wenn die unreinen Geister ihn sahen, fielen sie vor ihm nieder und schrien und sprachen: Du bist der Sohn Gottes*.", footnotes: ["℘ Kap. 1,24; Lk 4,34.41"] },
      { number: 12, text: "Und er bedrohte sie sehr, dass sie ihn nicht offenbar machten*.", footnotes: ["℘ Kap. 1,25.34.44"] },
      { number: 13, text: "*Und er steigt auf den Berg und ruft zu sich, die er wollte*. Und sie kamen zu ihm;", heading: "Berufung der zwölf Apostel", footnotes: ["℘ Mt 10,1-4; Lk 6,12-16; (Apg 1,13)", "℘ Joh 15,16 ⇨Esyn: Synopse Nr. 49"] },
      { number: 14, text: "und er berief* zwölf*, damit sie bei ihm seien und damit er sie aussende, zu predigen*", footnotes: ["w. machte", "℘ Kap. 6,7\nAndere alte Handschr. fügen hinzu: die er auch Apostel nannte", "℘ Lk 9,1.2"] },
      { number: 15, text: "und Vollmacht zu haben, die Dämonen auszutreiben*.", footnotes: ["℘ Kap. 6,12.13"] },
      { number: 16, text: "Und er berief* die Zwölf, und er gab dem Simon den Beinamen Petrus*,", footnotes: ["w. machte", "℘ Mt 4,18 ⇨Esyn: Synopse Nr. 21"] },
      { number: 17, text: "und Jakobus, den <Sohn> des Zebedäus, und Johannes, den Bruder des Jakobus, und er gab ihnen den Beinamen Boanerges, das ist Söhne des Donners*,", footnotes: ["℘ Lk 9,54"] },
      { number: 18, text: "und Andreas und Philippus und Bartholomäus und Matthäus und Thomas und Jakobus, den <Sohn> des Alphäus, und Thaddäus und Simon, den Kananäer*,", footnotes: ["wahrscheinlich von hebr. kana (d. h. eifern)"] },
      { number: 19, text: "und Judas Iskariot*, der ihn auch überlieferte*.", footnotes: ["Der Beiname bedeutete wahrscheinlich »Mann aus Kariot« und diente viell. zur Unterscheidung von dem anderen Jünger namens Judas (vgl. Joh 14,22).", "℘ Joh 18,2"] },
      { number: 20, text: "*Und er kommt in ein Haus. Und wieder kommt die Volksmenge zusammen, so dass sie nicht einmal Brot essen konnten*.", heading: "Lästerung des Geistes — Die wahren Verwandten Jesu", footnotes: ["℘ Mt 12,22-37; Lk 11,14-23", "℘ Kap. 6,31 ⇨Esyn: Synopse Nr. 116"] },
      { number: 21, text: "Und als seine Angehörigen es hörten, gingen sie los, um ihn zu greifen; denn sie sagten: Er ist von Sinnen*.", footnotes: ["℘ Joh 7,5; 10,20"] },
      { number: 22, text: "Und die Schriftgelehrten, die von Jerusalem herabgekommen waren, sagten: Er hat den Beelzebul*, und: Durch den Obersten der Dämonen treibt er die Dämonen aus*.", footnotes: ["Das ist im Judentum der Name für den Obersten der Dämonen; die Bedeutung des Namens ist umstritten.\n℘ Joh 7,20", "℘ Mt 9,34 ⇨Esyn: Synopse Nr. 117"] },
      { number: 23, text: "Und er rief sie zu sich und sprach in Gleichnissen zu ihnen: Wie kann Satan den Satan austreiben?" },
      { number: 24, text: "Und wenn ein Reich mit sich selbst entzweit ist, kann dieses Reich* nicht bestehen.", footnotes: ["o. diese Königsherrschaft"] },
      { number: 25, text: "Und wenn ein Haus mit sich selbst entzweit ist, wird dieses Haus nicht bestehen können." },
      { number: 26, text: "Und wenn der Satan gegen sich selbst aufgestanden und <mit sich> entzweit ist, kann er nicht bestehen, sondern er hat ein Ende." },
      { number: 27, text: "Niemand aber kann in das Haus des Starken eindringen und seinen Hausrat rauben, wenn er nicht vorher den Starken gebunden hat, und dann wird er sein Haus berauben." },
      { number: 28, text: "Wahrlich, ich sage euch: Alle Sünden werden den Söhnen der Menschen vergeben werden und die Lästerungen, mit denen sie auch lästern mögen*;", footnotes: ["℘ Lk 12,10 ⇨Esyn: Synopse Nr. 118"] },
      { number: 29, text: "wer aber gegen den Heiligen Geist lästern wird, hat keine Vergebung in Ewigkeit*, sondern ist ewiger Sünde schuldig* —", footnotes: ["griech. Äon", "℘ Lk 12,10"] },
      { number: 30, text: "weil sie sagten: Er hat einen unreinen Geist." },
      { number: 31, text: "*Und es kommen seine Mutter und seine Brüder*; und sie standen draußen, sandten zu ihm und riefen ihn.", footnotes: ["℘ Mt 12,46-50; Lk 8,19-21", "℘ Kap. 6,3 ⇨Esyn: Synopse Nr. 121"] },
      { number: 32, text: "Und eine Volksmenge saß um ihn her; sie sagten aber zu ihm: Siehe, deine Mutter und deine Brüder *und deine Schwestern* draußen suchen dich.", footnotes: ["in vielen alten Handschr. nicht enthalten", "in vielen alten Handschr. nicht enthalten"] },
      { number: 33, text: "Und er antwortete ihnen und spricht: Wer sind meine Mutter und meine Brüder?" },
      { number: 34, text: "Und er blickte umher auf die um ihn im Kreise Sitzenden und spricht: Siehe, meine Mutter und meine Brüder!" },
      { number: 35, text: "Wer den Willen Gottes tut, der ist mein Bruder und <meine> Schwester und <meine> Mutter. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 321"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "*Und wieder fing er an, am See zu lehren. Und es versammelt sich eine sehr große Volksmenge zu ihm, so dass er in ein Boot stieg und auf dem See saß; und die ganze Volksmenge war am See auf dem Land*.", heading: "Gleichnis vom Sämann", footnotes: ["℘ Mt 13,1-23; Lk 8,4-15", "℘ Kap. 3,9 ⇨Esyn: Synopse Nr. 122"] },
      { number: 2, text: "Und er lehrte sie vieles in Gleichnissen*; und er sprach zu ihnen in seiner Lehre:", footnotes: ["℘ V. 33.34"] },
      { number: 3, text: "Hört! Siehe, der Sämann ging hinaus, um zu säen." },
      { number: 4, text: "Und es geschah, indem er säte, fiel das eine an den Weg, und die Vögel kamen und fraßen es auf." },
      { number: 5, text: "Und anderes fiel auf das Steinige, wo es nicht viel Erde hatte; und es ging sogleich auf, weil es nicht tiefe Erde hatte." },
      { number: 6, text: "Und als die Sonne aufging, wurde es verbrannt, und weil es keine Wurzel hatte, verdorrte es." },
      { number: 7, text: "Und anderes fiel unter die Dornen; und die Dornen sprossten auf und erstickten es, und es gab keine Frucht." },
      { number: 8, text: "Und anderes fiel in die gute Erde und gab Frucht*, indem es aufsprosste und wuchs; und es trug eines dreißig-, eines sechzig- und eines hundert<fach>.", footnotes: ["℘ Kol 1,6"] },
      { number: 9, text: "Und er sprach: Wer Ohren hat zu hören, der höre*!", footnotes: ["℘ V. 23; Mt 11,15"] },
      { number: 10, text: "Und als er allein war, fragten ihn die, die um ihn waren, samt den Zwölfen nach den Gleichnissen. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 303"] },
      { number: 11, text: "Und er sprach zu ihnen: Euch ist das Geheimnis des Reiches* Gottes gegeben, jenen aber, die draußen sind*, wird alles in Gleichnissen zuteil,", footnotes: ["o. der Königsherrschaft", "℘ 1Kor 5,12; Kol 4,5; 1Thes 4,12; 1Tim 3,7; Offb 22,15"] },
      { number: 12, text: "»damit sie sehend sehen und nicht wahrnehmen und hörend hören und nicht verstehen*, damit sie sich nicht etwa bekehren und ihnen vergeben werde*«.", footnotes: ["℘ Röm 11,8", "℘ Jes 6,10; Joh 12,40 ⇨Esyn: Synopse Nr. 248"] },
      { number: 13, text: "Und er spricht zu ihnen: Begreift ihr dieses Gleichnis nicht? Und wie wollt ihr all die Gleichnisse verstehen? *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 124"] },
      { number: 14, text: "Der Sämann sät das Wort*.", footnotes: ["℘ 1Petr 1,23"] },
      { number: 15, text: "Die an dem Weg aber sind die, bei denen das Wort gesät wird und, wenn sie es hören, sogleich der Satan kommt und das Wort wegnimmt, das in sie hineingesät worden ist." },
      { number: 16, text: "Und ebenso sind die, die auf das Steinige gesät werden, die, wenn sie das Wort hören, es sogleich mit Freuden aufnehmen," },
      { number: 17, text: "und sie haben keine Wurzel in sich, sondern sind <Menschen> des Augenblicks; wenn nachher Bedrängnis oder Verfolgung um des Wortes willen entsteht, ärgern* sie sich sogleich*.", footnotes: ["Das griech. Wort bedeutet auch: Anstoß nehmen, zu Fall kommen, abfallen.", "℘ 2Tim 3,12"] },
      { number: 18, text: "Und andere sind die unter die Dornen Gesäten, es sind die, die das Wort gehört haben," },
      { number: 19, text: "und die Sorgen der Zeit* und der Betrug des Reichtums* und die Begierden nach den übrigen Dingen* kommen hinein und ersticken das Wort, und es bringt keine Frucht.", footnotes: ["o. dieses Zeitalters; o. dieser Welt; griech. Äon", "℘ Kap. 10,23.24", "℘ Lk 12,15"] },
      { number: 20, text: "Und die auf die gute Erde Gesäten sind jene, die das Wort hören und aufnehmen und Frucht bringen: eines dreißig- und eines sechzig- und eines hundert<fach>." },
      { number: 21, text: "*Und er sprach zu ihnen: Kommt* etwa die Lampe, damit sie unter den Scheffel* oder unter das Bett gestellt wird? Nicht damit sie auf das Lampengestell gestellt wird*?", heading: "Gleichnis von der Lampe", footnotes: ["℘ Lk 8,16-18", "d. h. Holt man", "w. Modios; s. Tabelle »Maße«", "℘ Mt 5,15 ⇨Esyn: Synopse Nr. 125"] },
      { number: 22, text: "Denn es ist nichts Verborgenes, das nicht offenbar gemacht werden soll, auch ist nichts Geheimes, das nicht ans Licht kommen soll*.", footnotes: ["℘ Mt 10,26"] },
      { number: 23, text: "Wenn jemand Ohren hat zu hören, der höre*!", footnotes: ["℘ V. 9"] },
      { number: 24, text: "Und er sprach zu ihnen: Seht zu, was ihr hört! Mit welchem Maß ihr messt, wird euch gemessen werden*, und es wird euch hinzugefügt werden.", footnotes: ["℘ Mt 7,2"] },
      { number: 25, text: "Denn wer hat, dem wird gegeben werden; und wer nicht hat, von dem wird auch, was er hat, genommen werden*.", footnotes: ["℘ Mt 13,12"] },
      { number: 26, text: "Und er sprach: Mit dem Reich* Gottes ist es so, wie wenn ein Mensch den Samen auf das Land wirft*", heading: "Gleichnis vom Aufwachsen der Saat", footnotes: ["o. der Königsherrschaft", "℘ Mt 13,24 ⇨Esyn: Synopse Nr. 126"] },
      { number: 27, text: "und schläft und aufsteht, Nacht und Tag, und der Same sprießt hervor und wächst, er weiß selbst nicht wie." },
      { number: 28, text: "Die Erde bringt von selbst Frucht hervor, zuerst Gras, dann eine Ähre, dann vollen Weizen in der Ähre*.", footnotes: ["℘ 1Mo 1,11; Ps 104,14; Jes 55,10"] },
      { number: 29, text: "Wenn aber die Frucht es zulässt, so schickt er sogleich die Sichel, denn die Ernte ist da*.", footnotes: ["℘ Joe 4,13; Offb 14,15"] },
      { number: 30, text: "*Und er sprach: Wie sollen wir das Reich* Gottes vergleichen? Oder in welchem Gleichnis sollen wir es darstellen? *", heading: "Gleichnis vom Senfkorn", footnotes: ["℘ Mt 13,31-35; Lk 13,18-21", "o. die Königsherrschaft", "℘ ⇨Esyn: Synopse Nr. 128"] },
      { number: 31, text: "Wie ein Senfkorn, das, wenn es auf die Erde gesät wird, kleiner ist als alle <Arten von> Samen, die auf der Erde sind;" },
      { number: 32, text: "und wenn es gesät ist, geht es auf und wird größer als alle Kräuter, und es treibt große Zweige, so dass unter seinem Schatten die Vögel des Himmels nisten können*. —", footnotes: ["℘ Hes 17,23"] },
      { number: 33, text: "Und in vielen solchen Gleichnissen redete er zu ihnen das Wort, wie sie es zu hören vermochten. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 130"] },
      { number: 34, text: "Ohne Gleichnis aber redete er nicht zu ihnen*; aber seinen Jüngern erklärte er alles besonders*.", footnotes: ["℘ V. 2; Kap. 12,1", "℘ Mt 13,11"] },
      { number: 35, text: "*Und an jenem Tag sagt er zu ihnen, als es Abend geworden war: Lasst uns zum jenseitigen Ufer übersetzen*!", heading: "Stillung des Sturms", footnotes: ["℘ Mt 8,23-27; Lk 8,22-25", "℘ Mt 8,18 ⇨Esyn: Synopse Nr. 136"] },
      { number: 36, text: "Und sie entließen die Volksmenge und nehmen ihn im Boot mit, wie er war. Und andere Boote waren bei ihm." },
      { number: 37, text: "Und es erhebt sich ein heftiger Sturmwind*, und die Wellen schlugen in das Boot, so dass das Boot sich schon füllte.", footnotes: ["℘ Joh 6,18"] },
      { number: 38, text: "Und er war hinten im Boot und schlief auf dem Kopfkissen; und sie wecken ihn auf und sprechen zu ihm: Lehrer, kümmert es dich nicht, dass wir umkommen*?", footnotes: ["℘ Ps 44,25"] },
      { number: 39, text: "Und er wachte auf, bedrohte den Wind und sprach zu dem See: Schweig, verstumme! Und der Wind legte sich, und es entstand eine große Stille*.", footnotes: ["℘ Kap. 6,51"] },
      { number: 40, text: "Und er sprach zu ihnen: Warum seid ihr furchtsam? Habt ihr noch keinen Glauben?" },
      { number: 41, text: "Und sie fürchteten sich mit großer Furcht* und sprachen zueinander: Wer ist denn dieser*, dass auch der Wind und der See ihm gehorchen?", footnotes: ["℘ Kap. 5,15", "℘ Kap. 1,27; Mt 21,10"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "*Und sie kamen an das jenseitige Ufer des Sees in das Land der Gerasener. *", heading: "Heilung eines besessenen Geraseners", footnotes: ["℘ Mt 8,28-34; Lk 8,26-39", "℘ ⇨Esyn: Synopse Nr. 137"] },
      { number: 2, text: "Und als er aus dem Boot gestiegen war, begegnete ihm sogleich von den Grüften her ein Mensch mit einem unreinen Geist," },
      { number: 3, text: "der seine Wohnung in den Grabstätten hatte; und selbst mit Ketten konnte ihn keiner mehr binden," },
      { number: 4, text: "da er oft mit Fußfesseln und mit Ketten gebunden worden war und die Ketten von ihm in Stücke zerrissen und die Fußfesseln zerrieben worden waren; und niemand konnte ihn bändigen." },
      { number: 5, text: "Und allezeit, Nacht und Tag, war er in den Grabstätten und auf den Bergen und schrie und zerschlug sich mit Steinen." },
      { number: 6, text: "Und als er Jesus von weitem sah, lief er und warf sich vor ihm nieder;" },
      { number: 7, text: "und er schrie mit lauter Stimme und sagt: Was habe ich mit dir zu schaffen, Jesus, Sohn Gottes, des Höchsten*? Ich beschwöre dich bei Gott, quäle mich nicht*!", footnotes: ["℘ Lk 1,32", "℘ Kap. 1,24; Jak 2,19"] },
      { number: 8, text: "Denn er sagte zu ihm: Fahre aus, du unreiner Geist, aus dem Menschen*!", footnotes: ["℘ Kap. 1,23.26"] },
      { number: 9, text: "Und er fragte ihn: Was ist dein Name? Und er spricht zu ihm: Legion ist mein Name, denn wir sind viele." },
      { number: 10, text: "Und er bat ihn sehr, dass er sie nicht aus der Gegend fortschicke." },
      { number: 11, text: "Es war aber dort an dem Berg eine große Herde Schweine, die weidete." },
      { number: 12, text: "Und sie baten ihn und sagten: Schicke uns in die Schweine, damit wir in sie hineinfahren!" },
      { number: 13, text: "Und er erlaubte es ihnen. Und die unreinen Geister fuhren aus und fuhren in die Schweine, und die Herde stürzte sich den Abhang hinab in den See, etwa zweitausend, und sie ertranken in dem See." },
      { number: 14, text: "Und ihre Hüter flohen und verkündeten es in der Stadt und auf dem Land; und sie kamen, um zu sehen, was geschehen war." },
      { number: 15, text: "Und sie kommen zu Jesus und sehen den Besessenen, der die Legion gehabt hatte, bekleidet und vernünftig sitzen, und sie fürchteten sich*.", footnotes: ["℘ Kap. 4,41"] },
      { number: 16, text: "Und die es gesehen hatten, erzählten ihnen, wie dem Besessenen geschehen war und das von den Schweinen." },
      { number: 17, text: "Und sie fingen an, ihn zu bitten, dass er aus ihrem Gebiet weggehe*.", footnotes: ["℘ Lk 19,14"] },
      { number: 18, text: "Und als er in das Boot stieg, bat ihn der, der besessen gewesen war, dass er bei ihm sein dürfe." },
      { number: 19, text: "Und er gestattete es ihm nicht, sondern spricht zu ihm: Geh in dein Haus zu den Deinen und verkünde ihnen, wie viel der Herr an dir getan und <wie er> sich deiner erbarmt hat." },
      { number: 20, text: "Und er ging hin und fing an, im Zehnstädtegebiet* auszurufen, wie viel Jesus an ihm getan hatte*; und alle wunderten sich.", footnotes: ["Landschaft mit zehn Städten im Nordosten Palästinas", "℘ Kap. 1,45; Ps 66,16"] },
      { number: 21, text: "*Und als Jesus in dem Boot wieder an das jenseitige Ufer hinübergefahren war, versammelte sich eine große Volksmenge zu ihm; und er war am See. *", heading: "Heilung der blutflüssigen Frau — Auferweckung der Tochter des Jaïrus", footnotes: ["℘ Mt 9,18-26; Lk 8,40-56", "℘ ⇨Esyn: Synopse Nr. 138"] },
      { number: 22, text: "Und es kommt einer der Synagogenvorsteher, mit Namen Jaïrus, und als er ihn sieht, fällt er ihm zu Füßen" },
      { number: 23, text: "und bittet ihn sehr und sagt: Mein Töchterchen liegt in den letzten Zügen. Komm, und lege ihr die Hände auf*, damit sie gerettet wird und lebt*!", footnotes: ["℘ Kap. 7,32", "℘ Joh 4,47"] },
      { number: 24, text: "Und er ging mit ihm, und eine große Volksmenge folgte ihm, und sie drängten ihn*.", footnotes: ["℘ Kap. 3,9"] },
      { number: 25, text: "Und <es war> eine Frau, die zwölf Jahre mit einem Blutfluss behaftet war*", footnotes: ["℘ 3Mo 15,25"] },
      { number: 26, text: "und vieles erlitten hatte von vielen Ärzten und alle ihre Habe aufgewendet und keinen Nutzen davon gehabt hatte; es war vielmehr schlimmer mit ihr geworden." },
      { number: 27, text: "Als sie von Jesus gehört hatte, kam sie in der Volksmenge von hinten und rührte sein Gewand an*;", footnotes: ["℘ Kap. 3,10"] },
      { number: 28, text: "denn sie sagte: Wenn ich nur sein Gewand* anrühre, werde ich geheilt* werden*.", footnotes: ["w. seine Gewänder", "w. gerettet", "℘ Kap. 3,10"] },
      { number: 29, text: "Und sogleich vertrocknete die Quelle ihres Blutes, und sie merkte am Leib, dass sie von der Plage geheilt war." },
      { number: 30, text: "Und sogleich erkannte Jesus in sich selbst die Kraft, die von ihm ausgegangen war, wandte sich um in der Volksmenge und sprach: Wer hat mein Gewand* angerührt*?", footnotes: ["w. meine Gewänder", "℘ Lk 6,19"] },
      { number: 31, text: "Und seine Jünger sagten zu ihm: Du siehst, dass die Volksmenge dich drängt*, und du sprichst: Wer hat mich angerührt?", footnotes: ["℘ Kap. 3,9"] },
      { number: 32, text: "Und er blickte umher, um die zu sehen, die dies getan hatte." },
      { number: 33, text: "Die Frau aber fürchtete sich und zitterte, da sie wusste, was ihr geschehen war, kam und fiel vor ihm nieder und sagte ihm die ganze Wahrheit." },
      { number: 34, text: "Er aber sprach zu ihr: Tochter, dein Glaube hat dich geheilt*. Geh hin in Frieden* und sei gesund von deiner Plage!", footnotes: ["w. gerettet\n℘ Kap. 10,52", "℘ 1Sam 1,17; 20,42; 2Kö 5,19"] },
      { number: 35, text: "Während er noch redete, kommen sie von <dem Haus> des Synagogenvorstehers und sagen: Deine Tochter ist gestorben, was bemühst du den Lehrer noch?" },
      { number: 36, text: "Jesus aber überhörte* das Wort, das geredet wurde, und spricht zu dem Synagogenvorsteher: Fürchte dich nicht; glaube nur*!", footnotes: ["o. hörte nebenbei", "℘ Kap. 9,23; 11,23; 2Chr 20,20; Joh 11,40"] },
      { number: 37, text: "Und er erlaubte niemand, ihn zu begleiten, außer Petrus und Jakobus und Johannes, dem Bruder des Jakobus*.", footnotes: ["℘ Kap. 9,2; 14,33; Mt 17,1"] },
      { number: 38, text: "Und sie kommen in das Haus des Synagogenvorstehers, und er sieht ein Getümmel und Weinende und laut Heulende." },
      { number: 39, text: "Und er geht hinein und sagt zu ihnen: Was lärmt und weint ihr? Das Kind ist nicht gestorben, sondern es schläft*.", footnotes: ["℘ Joh 11,11"] },
      { number: 40, text: "Und sie lachten ihn aus. Als er aber alle hinausgetrieben hatte, nimmt er den Vater des Kindes und die Mutter und die, die bei ihm waren, mit und geht hinein, wo das Kind war." },
      { number: 41, text: "Und er ergriff die Hand* des Kindes und spricht zu ihm: Talita kum! Das ist übersetzt: Mädchen, ich sage dir, steh auf*!", footnotes: ["℘ Kap. 1,31", "℘ Lk 7,14"] },
      { number: 42, text: "Und sogleich stand das Mädchen auf* und ging umher; es war nämlich zwölf Jahre alt. Und sie erstaunten sogleich mit großem Erstaunen*.", footnotes: ["℘ Mt 9,25", "℘ Kap. 6,51; 7,37; Lk 9,43"] },
      { number: 43, text: "Und er gebot ihnen dringend, dass niemand dies erfahren solle*, und er sagte, man solle ihr zu essen geben.", footnotes: ["℘ Kap. 1,44"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "*Und er ging von dort weg und kommt in seine Vaterstadt, und seine Jünger folgen ihm nach. *", heading: "Unglaube in Nazareth", footnotes: ["℘ Mt 13,53-58; vgl. Lk 4,16-30", "℘ ⇨Esyn: Synopse Nr. 139"] },
      { number: 2, text: "Und als es Sabbat geworden war, fing er an, in der Synagoge zu lehren; und viele, die zuhörten, erstaunten* und sagten: Woher <hat> der das? Und was ist das für eine Weisheit, die dem gegeben ist, und solche Wunderwerke* geschehen durch seine Hände*?", footnotes: ["℘ Kap. 11,18", "o. Machttaten; griech. dynamis", "℘ Joh 7,15 ⇨Esyn: Synopse Nr. 240"] },
      { number: 3, text: "Ist dieser nicht der Zimmermann*, der Sohn der Maria und ein Bruder des Jakobus* und Joses und Judas* und Simon*? Und sind nicht seine Schwestern hier bei uns? Und sie ärgerten* sich an ihm.", footnotes: ["℘ Jes 53,2", "℘ Apg 12,17", "℘ Jud 1", "℘ Kap. 3,31", "Das griech. Wort bedeutet auch: Anstoß nehmen, zu Fall kommen, zur Sünde verleitet werden."] },
      { number: 4, text: "Und Jesus sprach zu ihnen: Ein Prophet ist nicht ohne Ehre, außer in seiner Vaterstadt und unter seinen Verwandten und in seinem Haus*.", footnotes: ["℘ Joh 4,44 ⇨Esyn: Synopse Nr. 32"] },
      { number: 5, text: "Und er konnte dort kein Wunderwerk* tun, außer dass er wenigen Schwachen die Hände auflegte und sie heilte.", footnotes: ["o. keine Machttat; griech. dynamis"] },
      { number: 6, text: "Und er wunderte sich* über ihren Unglauben. Und er zog durch die Dörfer ringsum und lehrte*.", footnotes: ["℘ Mt 8,10", "℘ Mt 9,35 ⇨Esyn: Synopse Nr. 142"] },
      { number: 7, text: "*Und er ruft die Zwölf herbei*; und er fing an, sie zu zwei und zwei* auszusenden, und gab ihnen Vollmacht über die unreinen Geister*.", heading: "Aussendung der zwölf Apostel", footnotes: ["℘ Mt 10,5-15; Lk 9,1-6; vgl. Lk 10,1-12", "℘ Kap. 3,14", "℘ Pred 4,9", "℘ Mt 10,1"] },
      { number: 8, text: "Und er gebot ihnen, dass sie nichts mit auf den Weg nehmen sollten als nur einen Stab; kein Brot, keine Tasche, keine Münze im Gürtel*,", footnotes: ["℘ Lk 22,35"] },
      { number: 9, text: "sondern Sandalen untergebunden. Und zieht nicht zwei Unterkleider an!" },
      { number: 10, text: "Und er sprach zu ihnen: Wo ihr in ein Haus eintretet, dort bleibt, bis ihr von dort weggeht!" },
      { number: 11, text: "Und welcher Ort euch nicht aufnehmen und wo man euch nicht anhören wird, von dort geht hinaus und schüttelt den Staub ab, der unter euren Füßen ist, ihnen zum Zeugnis*!", footnotes: ["℘ Apg 13,51"] },
      { number: 12, text: "Und sie zogen aus und predigten, dass sie Buße tun sollten*;", footnotes: ["℘ Mt 3,2"] },
      { number: 13, text: "und sie trieben viele Dämonen aus* und salbten viele Schwache mit Öl und heilten sie*.", footnotes: ["℘ Lk 10,17", "℘ Kap. 3,15; Jak 5,14.15"] },
      { number: 14, text: "*Und der König Herodes* hörte <von ihm> — denn sein Name war bekannt geworden —, und sie sagten*: Johannes der Täufer ist aus den Toten auferweckt worden, und deswegen wirken die Wunderkräfte in ihm.", heading: "Der Tod des Täufers", footnotes: ["℘ Mt 14,1-12; Lk 3,19.20; 9,7-9", "Herodes Antipas, Sohn Herodes' d. Gr., unter röm. Oberherrschaft Fürst von Galiläa und Peräa (4 v. Chr. bis 39 n. Chr.)\n℘ Lk 3,1 ⇨Esyn: Synopse Nr. 143", "mit anderen Handschr.: und sagte"] },
      { number: 15, text: "Andere aber sagten: Es ist Elia; andere aber sagten: <Es ist> ein Prophet wie einer der Propheten*.", footnotes: ["℘ Kap. 8,28; Mal 3,23"] },
      { number: 16, text: "Als aber Herodes es hörte, sagte er: Johannes, den ich enthauptet habe, der ist auferweckt worden." },
      { number: 17, text: "Denn er, Herodes, hatte hingesandt und den Johannes greifen und ihn im Gefängnis binden lassen*, um der Herodias* willen, der Frau seines Bruders Philippus*, weil er sie geheiratet hatte.", footnotes: ["℘ Kap. 1,14 ⇨Esyn: Synopse Nr. 144", "Enkeltochter Herodes' d. Gr.; s. auch Anm. zu Mt 14,3", "Herodes Philippus; s. auch Anm. zu Mt 14,3"] },
      { number: 18, text: "Denn Johannes hatte dem Herodes gesagt: Es ist dir nicht erlaubt, die Frau deines Bruders zu haben*.", footnotes: ["℘ 3Mo 18,16"] },
      { number: 19, text: "Die Herodias aber trug <es> ihm nach und wollte ihn töten, und sie konnte nicht;" },
      { number: 20, text: "denn Herodes fürchtete den Johannes, da er wusste, dass er ein gerechter und heiliger Mann war, und er beschützte ihn; und wenn er ihn gehört hatte, war er in großer Verlegenheit, und er hörte ihn gern." },
      { number: 21, text: "Und als ein geeigneter Tag kam, als Herodes an seinem Geburtstag seinen Großen und den Obersten* und den Vornehmsten von Galiläa ein Gastmahl* gab,", footnotes: ["griech. Chiliarchen; d. h. Tausendschaftsführer", "s. Anm. zu Mt 23,6"] },
      { number: 22, text: "kam ihre, der Herodias, Tochter herein und tanzte, und sie gefiel dem Herodes und denen, die mit zu Tisch lagen. Und der König sprach zu dem Mädchen: Bitte mich, um was du willst! Und ich werde es dir geben." },
      { number: 23, text: "Und er schwor ihr: Um was du mich auch bitten wirst, ich werde es dir geben bis zur Hälfte meines Reiches*.", footnotes: ["℘ Est 5,3.6; 7,2"] },
      { number: 24, text: "Und sie ging hinaus und sagte zu ihrer Mutter: Um was soll ich bitten? Die aber sprach: Um das Haupt Johannes' des Täufers!" },
      { number: 25, text: "Und sie ging sogleich mit Eile zu dem König hinein und bat und sagte: Ich will, dass du mir sofort auf einer Schüssel das Haupt Johannes' des Täufers gibst!" },
      { number: 26, text: "Und der König wurde sehr betrübt; doch um der Eide und um derer willen, die mit zu Tisch lagen, wollte er sie nicht zurückweisen." },
      { number: 27, text: "Und sogleich schickte der König einen Henker und befahl, sein Haupt zu bringen. Und der ging hin und enthauptete ihn im Gefängnis." },
      { number: 28, text: "Und er brachte sein Haupt auf einer Schüssel und gab es dem Mädchen, und das Mädchen gab es ihrer Mutter*.", footnotes: ["℘ Kap. 9,13"] },
      { number: 29, text: "Und als seine Jünger es hörten, kamen sie und nahmen seinen Leichnam und legten ihn in eine Gruft." },
      { number: 30, text: "*Und die Apostel* versammeln sich zu Jesus; und sie berichteten ihm alles, was sie getan und was sie gelehrt hatten. *", heading: "Speisung der Fünftausend", footnotes: ["℘ Mt 14,13-21; Lk 9,10-17; Joh 6,1-15; vgl. Kap. 8,1-9; Mt 15,32-39", "d. h. Gesandte oder Boten", "℘ ⇨Esyn: Synopse Nr. 145"] },
      { number: 31, text: "Und er sprach zu ihnen: Kommt, ihr selbst allein, an einen öden Ort und ruht ein wenig aus! Denn diejenigen, die kamen und gingen, waren viele, und sie fanden nicht einmal Zeit, um zu essen*.", footnotes: ["℘ Kap. 3,20"] },
      { number: 32, text: "Und sie fuhren in einem Boot allein an einen öden Ort; *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 146"] },
      { number: 33, text: "und viele sahen sie wegfahren und erkannten sie und liefen zu Fuß von allen Städten dorthin zusammen und kamen ihnen zuvor." },
      { number: 34, text: "Und als Jesus aus <dem Boot> trat, sah er eine große Volksmenge und wurde innerlich bewegt* über sie; denn sie waren wie Schafe, die keinen Hirten haben*. Und er fing an, sie vieles zu lehren.", footnotes: ["℘ Kap. 1,41", "℘ Mt 9,36"] },
      { number: 35, text: "Und als es schon spät am Tag war, traten seine Jünger zu ihm und sagen: Der Ort ist öde, und es ist schon spät am Tag." },
      { number: 36, text: "Entlass sie, damit sie auf die umliegenden Höfe und in die Dörfer gehen und sich etwas zu essen kaufen!" },
      { number: 37, text: "Er aber antwortete und sprach zu ihnen: Gebt ihr ihnen zu essen! Und sie sagen zu ihm: Sollen wir hingehen und für zweihundert Denare Brot kaufen und ihnen zu essen geben?" },
      { number: 38, text: "Er aber spricht zu ihnen: Wie viele Brote habt ihr? Geht hin, seht nach! Und als sie es festgestellt hatten, sagen sie: Fünf und zwei Fische." },
      { number: 39, text: "Und er befahl ihnen, dass sie sich alle nach Tischgemeinschaften auf dem grünen Grase lagerten." },
      { number: 40, text: "Und sie lagerten sich in Gruppen zu je hundert und je fünfzig." },
      { number: 41, text: "Und er nahm die fünf Brote und die zwei Fische, blickte auf zum Himmel*, dankte und brach die Brote und gab sie den Jüngern, damit sie ihnen vorlegten; und die zwei Fische teilte er unter alle.", footnotes: ["℘ Kap. 7,34"] },
      { number: 42, text: "Und sie aßen alle und wurden gesättigt." },
      { number: 43, text: "Und sie hoben auf an Brocken zwölf Handkörbe voll und von den Fischen*.", footnotes: ["℘ Kap. 8,19"] },
      { number: 44, text: "Und diejenigen, die die Brote gegessen hatten, waren fünftausend Männer." },
      { number: 45, text: "*Und sogleich nötigte er seine Jünger, in das Boot zu steigen und an das jenseitige Ufer nach Betsaida vorauszufahren, während er selbst die Volksmenge entlässt. *", heading: "Jesus geht auf dem See", footnotes: ["℘ Mt 14,22-33; Joh 6,16-21", "℘ ⇨Esyn: Synopse Nr. 147"] },
      { number: 46, text: "Und nachdem er sie verabschiedet hatte, ging er auf den Berg, um zu beten*.", footnotes: ["℘ Kap. 1,35"] },
      { number: 47, text: "Und als es Abend geworden, war das Boot mitten auf dem See und er allein auf dem Land." },
      { number: 48, text: "Und als er sie beim Rudern Not leiden sah, denn der Wind war ihnen entgegen, kommt er um die vierte Nachtwache* zu ihnen, indem er auf dem See einherging*; und er wollte an ihnen vorübergehen*.", footnotes: ["In neutestamentl. Zeit galt die griech.-röm. Einteilung der Nacht in vier Nachtwachen; die hier angegebene Zeit liegt also zwischen drei und sechs Uhr morgens.", "℘ Hi 9,8", "℘ Lk 24,28"] },
      { number: 49, text: "Sie aber sahen ihn auf dem See einhergehen und meinten, es sei ein Gespenst, und schrien auf;" },
      { number: 50, text: "denn alle sahen ihn und wurden bestürzt. Er aber redet sogleich mit ihnen und spricht zu ihnen: Seid guten Mutes! Ich bin es. Fürchtet euch nicht!" },
      { number: 51, text: "Und er stieg zu ihnen in das Boot, und der Wind legte sich*. Und sie entsetzten sich sehr über die Maßen*;", footnotes: ["℘ Kap. 4,39", "℘ Kap. 5,42"] },
      { number: 52, text: "denn sie waren durch die Brote nicht verständig geworden, sondern ihr Herz war verhärtet*.", footnotes: ["℘ Kap. 8,17"] },
      { number: 53, text: "*Und als sie hinübergefahren waren, kamen sie in das Land Genezareth und legten an. *", heading: "Heilung vieler Kranker", footnotes: ["℘ Mt 14,34-36", "℘ ⇨Esyn: Synopse Nr. 148"] },
      { number: 54, text: "Und als sie aus dem Boot stiegen, erkannten sie ihn sogleich" },
      { number: 55, text: "und liefen in jener ganzen Gegend umher und fingen an, die Kranken auf den Betten hierhin und dorthin zu tragen, <von> wo sie hörten, dass er sei*.", footnotes: ["℘ Mt 4,24"] },
      { number: 56, text: "Und wo auch immer er in Dörfer oder Städte oder in Gehöfte hineinging, legten sie die Kranken auf den Marktplätzen hin und baten ihn, dass sie nur die Quaste seines Gewandes anrühren dürften; und alle, die ihn anrührten, wurden geheilt*.", footnotes: ["w. gerettet\n℘ Kap. 3,10"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "*Und es versammeln sich zu ihm die Pharisäer und einige der Schriftgelehrten, die von Jerusalem gekommen waren; *", heading: "Gottes Gebot steht höher als menschliche Überlieferung", footnotes: ["℘ Mt 15,1-20", "℘ ⇨Esyn: Synopse Nr. 150"] },
      { number: 2, text: "und als sie einige seiner Jünger mit unreinen, das ist ungewaschenen, Händen Brot essen sahen* —", footnotes: ["℘ Lk 11,38"] },
      { number: 3, text: "denn die Pharisäer und alle Juden essen nicht, wenn sie sich nicht sorgfältig* die Hände gewaschen haben, indem sie die Überlieferung der Ältesten* festhalten;", footnotes: ["w. mit der Faust; andere übersetzen: mit einer Hand voll Wasser", "o. der Alten; so auch V. 5"] },
      { number: 4, text: "und vom Markt <kommend>, essen sie nicht, wenn sie sich nicht gewaschen* haben; und vieles andere gibt es, was sie zu halten übernommen haben: Waschungen der Becher und Krüge und Kupfergefäße* —,", footnotes: ["o. gebadet", "Einige Handschr. fügen hinzu: und Betten\n℘ Mt 23,25"] },
      { number: 5, text: "fragen ihn die Pharisäer und die Schriftgelehrten: Warum leben deine Jünger nicht nach der Überlieferung* der Ältesten, sondern essen das Brot mit unreinen Händen?", footnotes: ["Vorschriften, die über das Gesetz hinaus das Leben bis ins Einzelne regelten und einengten und mit denen sich vor allem die Schriftgelehrten beschäftigten; die Pharisäer bemühten sich, die Überlieferungen genau einzuhalten."] },
      { number: 6, text: "Er aber sprach zu ihnen: Treffend hat Jesaja über euch Heuchler geweissagt, wie geschrieben steht: »Dieses Volk ehrt mich mit den Lippen, aber ihr Herz ist weit entfernt von mir." },
      { number: 7, text: "Vergeblich aber verehren sie mich, indem sie als Lehren Menschengebote lehren.«*", footnotes: ["℘ Jes 29,13; Tit 1,14"] },
      { number: 8, text: "Ihr gebt das Gebot Gottes preis und haltet die Überlieferung der Menschen fest.*", footnotes: ["Andere Handschr. fügen hinzu: Waschungen der Krüge und Becher und vieles andere dergleichen tut ihr."] },
      { number: 9, text: "Und er sprach zu ihnen: Trefflich hebt ihr das Gebot Gottes auf, damit ihr eure Überlieferung haltet." },
      { number: 10, text: "Denn Mose hat gesagt: »Ehre deinen Vater und deine Mutter!«*, und: »Wer Vater oder Mutter flucht, soll des Todes sterben.«*", footnotes: ["℘ Kap. 10,19; 2Mo 20,12; 5Mo 5,16; Eph 6,2", "℘ 2Mo 21,17; 3Mo 20,9"] },
      { number: 11, text: "Ihr aber sagt: Wenn ein Mensch zum Vater oder zur Mutter spricht: Korban — das ist eine Opfergabe — <sei das>, was dir von mir zugute gekommen wäre," },
      { number: 12, text: "lasst ihr ihn nichts mehr für Vater oder Mutter tun," },
      { number: 13, text: "indem ihr das Wort Gottes ungültig macht durch eure Überlieferung, die ihr überliefert habt*; und Ähnliches dergleichen tut ihr viel.", footnotes: ["℘ Jer 8,8"] },
      { number: 14, text: "Und als er die Volksmenge wieder herbeigerufen hatte, sprach er zu ihnen: Hört mich alle und versteht!" },
      { number: 15, text: "Da ist nichts, was von außerhalb des Menschen in ihn hineingeht, das ihn verunreinigen kann*, sondern was aus dem Menschen herausgeht, das ist es, was den Menschen verunreinigt*.", footnotes: ["℘ Apg 10,14", "℘ V. 20.23; Ps 106,39"] },
      { number: 16, text: "[T>]*", footnotes: ["Andere Handschr. fügen hinzu: Wenn jemand Ohren hat zu hören, der höre!"] },
      { number: 17, text: "Und als er von der Volksmenge weg in ein Haus eintrat, befragten ihn seine Jünger über das Gleichnis." },
      { number: 18, text: "Und er spricht zu ihnen: Seid auch ihr so unverständig? Begreift ihr nicht, dass alles, was von außen in den Menschen hineingeht, ihn nicht verunreinigen kann?" },
      { number: 19, text: "Denn es geht nicht in sein Herz hinein, sondern in den Bauch, und es geht heraus in den Abort. <Damit> erklärte er alle Speisen für rein*.", footnotes: ["w. reinigend alle Speisen; mit einigen Handschr.: in den Abort, der alle Speisen reinigt"] },
      { number: 20, text: "Er sagte aber: Was aus dem Menschen herauskommt, das verunreinigt den Menschen." },
      { number: 21, text: "Denn von innen aus dem Herzen der Menschen kommen die bösen Gedanken hervor*: Unzucht*, Dieberei, Mord,", footnotes: ["℘ 1Mo 8,21; Jer 17,9; Mt 15,19", "o. Hurerei"] },
      { number: 22, text: "Ehebruch, Habsucht, Bosheit*, Arglist, Ausschweifung, Neid*, Lästerung, Hochmut, Torheit;", footnotes: ["Im Griech. stehen die Wörter »Unzucht« bis »Bosheit« in der Mehrzahl.", "w. böses Auge; Ausdruck aus dem Hebräischen (Semitismus)"] },
      { number: 23, text: "alle diese bösen Dinge kommen von innen heraus und verunreinigen den Menschen*.", footnotes: ["℘ V. 15"] },
      { number: 24, text: "*Von dort aber brach er auf und ging weg in das Gebiet von Tyrus; und er trat in ein Haus und wollte, dass niemand es erfahre*; und er konnte nicht verborgen sein.", heading: "Heilung der Tochter der Syro-Phönizierin", footnotes: ["℘ Mt 15,21-28", "℘ Jes 42,2 ⇨Esyn: Synopse Nr. 151"] },
      { number: 25, text: "Aber sogleich hörte eine Frau von ihm, deren Töchterchen einen unreinen Geist hatte, kam und fiel nieder zu seinen Füßen*;", footnotes: ["℘ Lk 8,41"] },
      { number: 26, text: "die Frau aber war eine Griechin, eine Syro-Phönizierin von Geburt; und sie bat ihn, dass er den Dämon von ihrer Tochter austreibe." },
      { number: 27, text: "Und er sprach zu ihr: Lass zuerst die Kinder satt werden, denn es ist nicht schön, das Brot der Kinder zu nehmen und den Hunden hinzuwerfen." },
      { number: 28, text: "Sie aber antwortete und spricht zu ihm: Ja, Herr, auch die Hunde essen unter dem Tisch von den Krumen der Kinder." },
      { number: 29, text: "Und er sprach zu ihr: Um dieses Wortes willen geh hin! Der Dämon ist aus deiner Tochter ausgefahren." },
      { number: 30, text: "Und sie ging weg in ihr Haus* und fand das Kind auf dem Bett liegen und den Dämon ausgefahren.", footnotes: ["℘ Joh 4,50"] },
      { number: 31, text: "Und er verließ das Gebiet von Tyrus und kam über Sidon an den See von Galiläa*, mitten in das Zehnstädtegebiet*.", heading: "Heilung eines Taubstummen", footnotes: ["℘ Mt 15,29; Joh 7,1 ⇨Esyn: Synopse Nr. 152", "Landschaft mit zehn Städten im Nordosten Palästinas"] },
      { number: 32, text: "Und sie bringen einen Tauben zu ihm, der mit Mühe redete, und bitten ihn, dass er ihm die Hand auflege*.", footnotes: ["℘ Kap. 5,23"] },
      { number: 33, text: "Und er nahm ihn von der Volksmenge beiseite, legte seine Finger in seine Ohren und berührte mit Speichel* seine Zunge*,", footnotes: ["w. berührte speiend", "℘ Kap. 8,23; Joh 9,6"] },
      { number: 34, text: "und er blickte zum Himmel*, seufzte* und spricht zu ihm: Hefata! Das ist: Werde geöffnet!", footnotes: ["℘ Kap. 6,41", "℘ Joh 11,33.38"] },
      { number: 35, text: "Und sogleich wurden seine Ohren geöffnet, und die Fessel seiner Zunge wurde gelöst, und er redete richtig." },
      { number: 36, text: "Und er gebot ihnen, dass sie es niemand sagen sollten*. Je mehr er es ihnen aber gebot, desto mehr machten sie es über alle Maßen bekannt;", footnotes: ["℘ Kap. 1,44.45"] },
      { number: 37, text: "und sie gerieten in höchstem Maß außer sich und sprachen: Er hat alles wohlgemacht; er macht sowohl die Tauben hören als auch die Stummen reden*.", footnotes: ["℘ Kap. 5,42; Jes 35,5; Mt 15,31"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "*Als in jenen Tagen wieder eine große Volksmenge da war und nichts zu essen hatte, rief er seine Jünger zu sich und spricht zu ihnen: *", heading: "Speisung der Viertausend", footnotes: ["℘ Mt 15,32-39; vgl. Mk 6,30-44; Mt 14,13-21; Lk 9,10-17; Joh 6,1-14", "℘ ⇨Esyn: Synopse Nr. 153"] },
      { number: 2, text: "Ich bin innerlich bewegt* über die Volksmenge, denn schon drei Tage harren sie bei mir aus und haben nichts zu essen;", footnotes: ["℘ Kap. 1,41"] },
      { number: 3, text: "und wenn ich sie hungrig nach Hause entlasse, so werden sie auf dem Weg verschmachten; und einige von ihnen sind von weit her gekommen." },
      { number: 4, text: "Und seine Jünger antworteten ihm: Woher wird jemand diese hier in der Einöde mit Brot sättigen können*?", footnotes: ["℘ 4Mo 11,13; 2Kö 4,43"] },
      { number: 5, text: "Und er fragte sie: Wie viele Brote habt ihr? Sie aber sagten: Sieben." },
      { number: 6, text: "Und er gebietet der Volksmenge, sich auf der Erde zu lagern. Und er nahm die sieben Brote, dankte*, brach sie und gab sie den Jüngern, damit sie vorlegten; und sie legten der Volksmenge vor.", footnotes: ["℘ Apg 27,35"] },
      { number: 7, text: "Und sie hatten einige kleine Fische; und er segnete sie und ließ auch sie vorlegen." },
      { number: 8, text: "Und sie aßen und wurden gesättigt; und sie hoben auf, was an Brocken übrig blieb, sieben Körbe*.", footnotes: ["℘ V. 20"] },
      { number: 9, text: "Es waren aber etwa viertausend; und er entließ sie." },
      { number: 10, text: "*Und er stieg sogleich mit seinen Jüngern in das Boot und kam in die Gegend von Dalmanuta.", heading: "Zeichenforderung — Warnung vor dem Sauerteig der Pharisäer und des Herodes", footnotes: ["℘ Mt 16,1-12"] },
      { number: 11, text: "Und die Pharisäer kamen heraus und fingen an, mit ihm zu streiten, indem sie von ihm ein Zeichen vom Himmel begehrten*, um ihn zu versuchen*.", footnotes: ["℘ Lk 11,16", "℘ Kap. 3,2 ⇨Esyn: Synopse Nr. 154"] },
      { number: 12, text: "Und er seufzte auf in seinem Geist und spricht: Was begehrt dieses Geschlecht ein Zeichen? Wahrlich, ich sage euch: Nimmermehr wird diesem Geschlecht ein Zeichen gegeben werden*!", footnotes: ["w. Wenn diesem Geschlecht ein Zeichen gegeben wird\n℘ Lk 11,29"] },
      { number: 13, text: "Und er ließ sie <stehen>, stieg wieder ein und fuhr an das jenseitige Ufer." },
      { number: 14, text: "Und sie vergaßen, Brote mitzunehmen, und außer einem Brot hatten sie nichts bei sich auf dem Boot. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 155"] },
      { number: 15, text: "Und er gebot ihnen und sprach: Seht zu, hütet euch vor dem Sauerteig der Pharisäer* und dem Sauerteig des Herodes!", footnotes: ["religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte\n℘ Lk 12,1"] },
      { number: 16, text: "Und sie überlegten miteinander: <Das sagt er,> weil wir keine Brote haben." },
      { number: 17, text: "Und er erkannte es und spricht zu ihnen: Was überlegt ihr, weil ihr keine Brote habt? Begreift ihr noch nicht und versteht ihr nicht*? Habt ihr euer Herz verhärtet*?", footnotes: ["℘ Mt 15,16", "℘ Kap. 6,52 ⇨Esyn: Synopse Nr. 303"] },
      { number: 18, text: "Augen habt ihr und seht nicht? Und Ohren habt ihr und hört nicht*? Und erinnert ihr euch nicht,", footnotes: ["℘ Hes 12,2; Mt 13,13"] },
      { number: 19, text: "als ich die fünf Brote unter die Fünftausend brach, wie viele Handkörbe voll Brocken ihr aufgehoben habt? Sie sagen zu ihm: Zwölf*.", footnotes: ["℘ Kap. 6,43"] },
      { number: 20, text: "Als <ich> die sieben unter die Viertausend <brach>, wie viele Körbe voll Brocken habt ihr aufgehoben? Und sie sagen: Sieben*.", footnotes: ["℘ V. 6-9"] },
      { number: 21, text: "Und er sprach zu ihnen: Versteht ihr noch nicht?" },
      { number: 22, text: "*Und sie kommen nach Betsaida; und sie bringen ihm einen Blinden und bitten ihn, dass er ihn anrühre. *", heading: "Heilung eines Blinden", footnotes: ["℘ vgl. Kap. 10,46-52; Mt 9,27-31; 20,29-34; Lk 18,35-43", "℘ ⇨Esyn: Synopse Nr. 156"] },
      { number: 23, text: "Und er fasste den Blinden bei der Hand und führte ihn aus dem Dorf hinaus*; und als er in seine Augen gespien <und> ihm die Hände aufgelegt hatte, fragte er ihn: Siehst du etwas?", footnotes: ["℘ Kap. 7,32.33"] },
      { number: 24, text: "Und er blickte auf und sagte: Ich sehe die Menschen, denn ich sehe sie wie Bäume umhergehen." },
      { number: 25, text: "Dann legte er wieder die Hände auf seine Augen, und er sah deutlich, und er war wiederhergestellt und sah alles klar*.", footnotes: ["℘ Ps 146,8; Joh 9,7"] },
      { number: 26, text: "Und er schickte ihn nach seinem Haus und sprach: Auch nicht ins Dorf sollst du gehen*!", footnotes: ["℘ Kap. 1,44"] },
      { number: 27, text: "*Und Jesus und seine Jünger gingen hinaus in die Dörfer von Cäsarea Philippi. Und auf dem Weg fragte er seine Jünger und sprach zu ihnen: Was sagen die Menschen, wer ich bin? *", heading: "Das Bekenntnis des Petrus", footnotes: ["℘ Mt 16,13-20; Lk 9,18-21", "℘ ⇨Esyn: Synopse Nr. 158"] },
      { number: 28, text: "Sie aber antworteten ihm und sagten: Johannes der Täufer; und andere: Elia; andere aber: einer der Propheten*.", footnotes: ["℘ Kap. 6,14.15"] },
      { number: 29, text: "Und er fragte sie: Ihr aber, was sagt ihr, wer ich bin? Petrus antwortet und spricht zu ihm: Du bist der Christus*.", footnotes: ["℘ Joh 1,41; 1Jo 5,1"] },
      { number: 30, text: "Und er redete ihnen ernstlich zu, dass sie mit niemandem über ihn reden sollten*.", footnotes: ["℘ Kap. 9,9"] },
      { number: 31, text: "*Und er fing an, sie zu lehren: Der Sohn des Menschen muss vieles leiden und verworfen werden von den Ältesten und Hohenpriestern* und Schriftgelehrten und getötet werden und nach drei Tagen auferstehen*.", heading: "Erste Leidensankündigung — Bedingungen der Nachfolge", footnotes: ["℘ Mt 16,21-28; Lk 9,22-27", "Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet.", "℘ Mt 16,21 ⇨Esyn: Synopse Nr. 159"] },
      { number: 32, text: "Und er redete das Wort mit Offenheit. Und Petrus nahm ihn beiseite und fing an, ihn zu tadeln." },
      { number: 33, text: "Er aber wandte sich um und sah seine Jünger und tadelte Petrus und sagte: Geh weg hinter mich, Satan! Denn du sinnst nicht auf das, was Gottes, sondern auf das, was der Menschen ist." },
      { number: 34, text: "Und als er die Volksmenge samt seinen Jüngern herzugerufen hatte, sprach er zu ihnen: Wenn jemand mir nachkommen* will, verleugne er sich selbst und nehme sein Kreuz auf und folge mir nach*!", footnotes: ["mit anderen Handschr.: nachfolgen", "℘ Kap. 10,21 ⇨Esyn: Synopse Nr. 302"] },
      { number: 35, text: "Denn wer sein Leben* retten will, wird es verlieren; wer aber sein Leben* verliert um meinetwillen und um des Evangeliums willen, wird es retten*.", footnotes: ["o. seine Seele; so auch V. 36—37", "o. seine Seele; so auch V. 36—37", "℘ Mt 10,39 ⇨Esyn: Synopse Nr. 235"] },
      { number: 36, text: "Denn was nützt es einem Menschen, die ganze Welt zu gewinnen und sein Leben einzubüßen?" },
      { number: 37, text: "Denn was könnte ein Mensch als Lösegeld für sein Leben geben*?", footnotes: ["℘ Ps 49,9"] },
      { number: 38, text: "Denn wer sich meiner und meiner Worte schämt unter diesem ehebrecherischen und sündigen Geschlecht, dessen wird sich auch der Sohn des Menschen schämen*, wenn er kommen wird in der Herrlichkeit seines Vaters mit den heiligen Engeln*.", footnotes: ["℘ Mt 10,33", "℘ Mt 25,31 ⇨Esyn: Synopse Nr. 300"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und er sprach zu ihnen: Wahrlich, ich sage euch: Es sind einige von denen, die hier stehen, die den Tod nicht schmecken werden, bis sie das Reich* Gottes in Kraft haben kommen sehen. *", footnotes: ["o. die Königsherrschaft", "℘ ⇨Esyn: Synopse Nr. 367"] },
      { number: 2, text: "*Und nach sechs Tagen nimmt Jesus Petrus und Jakobus und Johannes* mit und führt sie für sich allein auf einen hohen Berg. Und er wurde vor ihnen umgestaltet;", heading: "Die Verklärung Jesu", footnotes: ["℘ Mt 17,1-13; Lk 9,28-36; 2Petr 1,16-18", "℘ Kap. 5,37 ⇨Esyn: Synopse Nr. 161"] },
      { number: 3, text: "und seine Kleider wurden glänzend, sehr weiß, so wie kein Walker* auf der Erde weiß machen kann.", footnotes: ["Aufgabe des Walkers war es, Stoffe zu bearbeiten (Entfetten, Bleichen, Verfilzen)."] },
      { number: 4, text: "Und es erschien ihnen Elia mit Mose, und sie unterredeten sich mit Jesus." },
      { number: 5, text: "Und Petrus begann* und sagte zu Jesus: Rabbi*, es ist gut, dass wir hier sind; und wir wollen drei Hütten machen, dir eine und Mose eine und Elia eine.", footnotes: ["w. antwortete; hier in semitisierender Redeweise für den Anfang einer Rede gebraucht", "d. h. Mein Meister!; respektvolle Anrede der geistlichen Lehrer im Spätjudentum"] },
      { number: 6, text: "Er wusste nämlich nicht, was er sagen sollte, denn sie waren voller Furcht." },
      { number: 7, text: "Und es kam eine Wolke*, die sie überschattete; und eine Stimme kam aus der Wolke: Dieser ist mein geliebter Sohn*, ihn hört*!", footnotes: ["℘ 2Mo 40,34; 1Kö 8,10", "℘ Kap. 1,11; 12,6", "℘ Apg 3,22 ⇨Esyn: Synopse Nr. 302"] },
      { number: 8, text: "Und plötzlich, als sie sich umblickten, sahen sie niemand mehr bei sich außer Jesus allein." },
      { number: 9, text: "Und als sie von dem Berg herabstiegen, gebot er ihnen, dass sie niemand erzählen sollten, was sie gesehen hatten, ehe nicht der Sohn des Menschen aus den Toten auferstanden sei*.", footnotes: ["℘ Kap. 8,30 ⇨Esyn: Synopse Nr. 163"] },
      { number: 10, text: "Und sie hielten das Wort fest und besprachen sich untereinander: Was ist das, aus den Toten auferstehen*?", footnotes: ["℘ V. 32; Lk 18,34"] },
      { number: 11, text: "Und sie fragten ihn und sprachen: Warum sagen die Schriftgelehrten, dass Elia zuerst kommen müsse*?", footnotes: ["℘ Lk 1,17 ⇨Esyn: Synopse Nr. 162"] },
      { number: 12, text: "Er aber sprach zu ihnen: Elia kommt zwar zuerst* und stellt alle Dinge wieder her. Und wie steht über den Sohn des Menschen geschrieben? Dass er vieles leiden und verachtet werden soll*.", footnotes: ["℘ Mal 3,23", "℘ Jes 53,3"] },
      { number: 13, text: "Aber ich sage euch: Auch Elia ist gekommen*, und sie haben ihm getan, was sie wollten*, so wie über ihn geschrieben steht*.", footnotes: ["℘ Mt 11,14", "℘ Kap. 6,28", "℘ 1Kö 19,2.10"] },
      { number: 14, text: "*Und als sie zu den <übrigen> Jüngern kamen, sahen sie eine große Volksmenge um sie her und Schriftgelehrte, die mit ihnen stritten.", heading: "Heilung eines Fallsüchtigen", footnotes: ["℘ Mt 17,14-21; Lk 9,37-43"] },
      { number: 15, text: "Und sobald die ganze Volksmenge ihn sah, erstaunte sie sehr; und sie liefen herbei und begrüßten ihn." },
      { number: 16, text: "Und er fragte sie: Worüber streitet ihr mit ihnen?" },
      { number: 17, text: "Und einer aus der Volksmenge antwortete ihm: Lehrer, ich habe meinen Sohn zu dir gebracht, der einen stummen Geist hat*;", footnotes: ["℘ Lk 11,14"] },
      { number: 18, text: "und wo er ihn auch ergreift, zerrt er ihn zu Boden, und er schäumt und knirscht mit den Zähnen und wird starr. Und ich sagte deinen Jüngern, dass sie ihn austreiben möchten, und sie konnten es nicht*.", footnotes: ["℘ 2Kö 4,31"] },
      { number: 19, text: "Er aber antwortete ihnen und spricht: Ungläubiges Geschlecht! Bis wann soll ich bei euch sein? Bis wann soll ich euch ertragen? Bringt ihn zu mir!" },
      { number: 20, text: "Und sie brachten ihn zu ihm. Und als der Geist ihn sah, zerrte er ihn sogleich; und er fiel zur Erde, wälzte sich und schäumte." },
      { number: 21, text: "Und er fragte seinen Vater: Wie lange ist es her, dass ihm dies geschehen ist? Er aber sagte: Von Kindheit an;" },
      { number: 22, text: "und oft hat er ihn bald ins Feuer, bald ins Wasser geworfen, um ihn umzubringen. Aber wenn du etwas kannst, so habe Erbarmen mit uns und hilf uns!" },
      { number: 23, text: "Jesus aber sprach zu ihm: Wenn du das kannst? Dem Glaubenden ist alles möglich*.", footnotes: ["℘ Kap. 5,36"] },
      { number: 24, text: "Sogleich schrie der Vater des Kindes und sagte: Ich glaube. Hilf meinem Unglauben*!", footnotes: ["℘ Mt 9,28; Lk 17,5"] },
      { number: 25, text: "Als aber Jesus sah, dass eine Volksmenge zusammenläuft, bedrohte er den unreinen Geist und sprach zu ihm: Du stummer und tauber Geist, ich gebiete dir: Fahre von ihm aus, und fahre nicht mehr in ihn hinein!*", footnotes: ["℘ Lk 8,29"] },
      { number: 26, text: "Und er schrie und zerrte <ihn> heftig und fuhr aus*; und er wurde wie tot, so dass die meisten sagten: Er ist gestorben.", footnotes: ["℘ Kap. 1,25.26"] },
      { number: 27, text: "Jesus aber nahm ihn bei der Hand, richtete ihn auf, und er stand auf*.", footnotes: ["℘ Kap. 1,31"] },
      { number: 28, text: "Und als er in ein Haus gegangen war, fragten ihn seine Jünger allein*: Warum haben wir ihn nicht austreiben können?", footnotes: ["℘ Kap. 10,10"] },
      { number: 29, text: "Und er sprach zu ihnen: Diese Art kann durch nichts ausfahren als nur durch Gebet*.", footnotes: ["Andere Handschr. fügen hinzu: und Fasten"] },
      { number: 30, text: "*Und sie gingen von dort weg und zogen durch Galiläa; und er wollte nicht, dass es jemand erfuhr. *", heading: "Zweite Leidensankündigung", footnotes: ["℘ Mt 17,22.23; Lk 9,43-45", "℘ ⇨Esyn: Synopse Nr. 164"] },
      { number: 31, text: "Denn er lehrte seine Jünger und sprach zu ihnen: Der Sohn des Menschen wird überliefert in der Menschen Hände, und sie werden ihn töten; und nachdem er getötet worden ist, wird er nach drei Tagen auferstehen*.", footnotes: ["℘ Mt 16,21"] },
      { number: 32, text: "Sie aber verstanden die Rede nicht* und fürchteten sich, ihn zu fragen*.", footnotes: ["℘ V. 10", "℘ Kap. 10,32"] },
      { number: 33, text: "*Und sie kamen nach Kapernaum, und als er im Hause war, fragte er sie: Was habt ihr unterwegs besprochen? *", heading: "Maßstäbe für wahre Größe und den Dienst im Reich Gottes", footnotes: ["℘ Mt 18,1-5; Lk 9,46-48", "℘ ⇨Esyn: Synopse Nr. 166"] },
      { number: 34, text: "Sie aber schwiegen; denn sie hatten sich auf dem Weg untereinander besprochen, wer der Größte sei*.", footnotes: ["℘ Lk 22,24"] },
      { number: 35, text: "Und er setzte sich, rief die Zwölf, und er spricht zu ihnen: Wenn jemand der Erste sein will, soll er der Letzte von allen und aller Diener sein*.", footnotes: ["℘ Kap. 10,44 ⇨Esyn: Synopse Nr. 313"] },
      { number: 36, text: "Und er nahm ein Kind und stellte es in ihre Mitte; und er nahm es in seine Arme* und sprach zu ihnen:", footnotes: ["℘ Kap. 10,16"] },
      { number: 37, text: "Wer eins von solchen Kindern aufnehmen wird in meinem Namen, nimmt mich auf; und wer mich aufnehmen wird, nimmt nicht mich auf, sondern den, der mich gesandt hat*.", footnotes: ["℘ Mt 10,40"] },
      { number: 38, text: "*Johannes sagte zu ihm: Lehrer, wir sahen jemand Dämonen austreiben in deinem Namen; und wir wehrten ihm, weil er uns nicht nachfolgt*.", footnotes: ["℘ Lk 9,49.50", "℘ 4Mo 11,27.28 ⇨Esyn: Synopse Nr. 167"] },
      { number: 39, text: "Jesus aber sprach: Wehrt ihm nicht, denn es ist niemand, der ein Wunder* in meinem Namen tun und bald darauf schlecht von mir reden kann.", footnotes: ["o. eine Machttat; griech. dynamis"] },
      { number: 40, text: "Denn wer nicht gegen uns ist, ist für uns*.", footnotes: ["℘ Mt 12,30"] },
      { number: 41, text: "Denn wer euch einen Becher Wasser zu trinken geben wird aufgrund dessen, dass* ihr Christus angehört, wahrlich, ich sage euch: Er wird seinen Lohn gewiss nicht verlieren*.", footnotes: ["w. im Namen, weil; andere Handschr. haben: in meinem Namen, weil", "℘ Mt 10,42 ⇨Esyn: Synopse Nr. 104"] },
      { number: 42, text: "*Und wer einem dieser Kleinen, die an mich glauben, Anlass zur Sünde gibt*, für den wäre es besser, wenn ein Mühlstein um seinen Hals gelegt und er ins Meer geworfen würde*.", heading: "Warnung vor Verführung zur Sünde", footnotes: ["℘ Mt 18,6-10", "o. Anstoß gibt; o. ärgert", "℘ Lk 17,2 ⇨Esyn: Synopse Nr. 168"] },
      { number: 43, text: "Und wenn deine Hand dir Anlass zur Sünde gibt*, so hau sie ab! Es ist besser für dich, als Krüppel in das Leben hineinzugehen, als mit zwei Händen in die Hölle* zu kommen, in das unauslöschliche Feuer*.", footnotes: ["o. Anstoß gibt; o. ärgert", "℘ Mt 5,22", "℘ Mt 5,30; 25,41"] },
      { number: 44, text: "[T>]*", footnotes: ["Andere Handschr. fügen hinzu: wo ihr Wurm nicht stirbt und das Feuer nicht erlischt."] },
      { number: 45, text: "Und wenn dein Fuß dir Anlass zur Sünde gibt*, so hau ihn ab! Es ist besser für dich, lahm in das Leben hineinzugehen, als mit zwei Füßen in die Hölle geworfen zu werden.", footnotes: ["o. Anstoß gibt; o. ärgert"] },
      { number: 46, text: "[T>]*", footnotes: ["Andere Handschr. fügen hinzu: in das unauslöschliche Feuer, 46 wo ihr Wurm nicht stirbt und das Feuer nicht erlischt."] },
      { number: 47, text: "Und wenn dein Auge dir Anlass zur Sünde gibt*, so wirf es weg! Es ist besser für dich, einäugig in das Reich* Gottes hineinzugehen, als mit zwei Augen in die Hölle geworfen zu werden*,", footnotes: ["o. Anstoß gibt; o. ärgert", "o. die Königsherrschaft", "℘ Mt 5,29"] },
      { number: 48, text: "»wo ihr Wurm nicht stirbt und das Feuer nicht erlischt*«.", footnotes: ["℘ Jes 66,24; Mt 3,12; Offb 14,10.11"] },
      { number: 49, text: "Denn jeder wird mit Feuer gesalzen werden*.", footnotes: ["Andere Handschr. fügen hinzu: und jedes Schlachtopfer wird mit Salz gesalzen werden\n℘ 3Mo 2,13"] },
      { number: 50, text: "Das Salz ist gut; wenn aber das Salz salzlos geworden ist, womit wollt ihr es würzen*? Habt Salz in euch selbst*, und haltet Frieden untereinander*!", footnotes: ["℘ Mt 5,13", "℘ Kol 4,6", "℘ Röm 14,19; 2Kor 13,11; 1Thes 5,13"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "*Und er brach von dort auf und kommt in das Gebiet von Judäa und jenseits des Jordan. Und wieder kommen Volksmengen bei ihm zusammen, und wie er gewohnt war, lehrte er sie wieder*.", heading: "Ehe und Ehescheidung", footnotes: ["℘ Mt 19,1-12", "℘ Joh 10,40 ⇨Esyn: Synopse Nr. 251"] },
      { number: 2, text: "Und es traten Pharisäer zu <ihm> und fragten ihn, um ihn zu versuchen*: Ist es einem Mann erlaubt, <seine> Frau zu entlassen?", footnotes: ["℘ Kap. 3,2 ⇨Esyn: Synopse Nr. 252"] },
      { number: 3, text: "Er aber antwortete und sprach zu ihnen: Was hat euch Mose geboten?" },
      { number: 4, text: "Sie aber sagten: Mose hat gestattet, einen Scheidebrief zu schreiben und zu entlassen*.", footnotes: ["℘ 5Mo 24,1; Mt 5,31"] },
      { number: 5, text: "Jesus aber sprach zu ihnen: Wegen eurer Herzenshärtigkeit hat er euch dieses Gebot geschrieben;" },
      { number: 6, text: "von Anfang der Schöpfung an aber hat er sie <als> Mann und Frau* geschaffen*.", footnotes: ["w. männlich und weiblich", "℘ 1Mo 1,27; 5,2"] },
      { number: 7, text: "»Darum wird ein Mensch seinen Vater und seine Mutter verlassen*,", footnotes: ["Andere Handschr. fügen hinzu: und seiner Frau anhängen"] },
      { number: 8, text: "und die zwei werden ein Fleisch sein*«; daher sind sie nicht mehr zwei, sondern ein Fleisch.", footnotes: ["℘ 1Mo 2,24; Eph 5,31"] },
      { number: 9, text: "Was nun Gott zusammengefügt hat, soll <der> Mensch nicht scheiden*.", footnotes: ["℘ Mal 2,16; 1Kor 7,10"] },
      { number: 10, text: "Und im Hause befragten ihn die Jünger deswegen noch einmal*.", footnotes: ["℘ Kap. 9,28"] },
      { number: 11, text: "Und er spricht zu ihnen: Wer seine Frau entlässt und eine andere heiratet, begeht Ehebruch gegen sie*.", footnotes: ["℘ Mt 5,32 ⇨Esyn: Synopse Nr. 56"] },
      { number: 12, text: "Und wenn sie ihren Mann entlässt und einen anderen heiratet, begeht sie Ehebruch*.", footnotes: ["℘ Röm 7,3"] },
      { number: 13, text: "*Und sie brachten Kinder zu ihm, damit er sie anrührte. Die Jünger aber fuhren sie an. *", heading: "Jesus und die Kinder", footnotes: ["℘ Mt 19,13-15; Lk 18,15-17", "℘ ⇨Esyn: Synopse Nr. 253"] },
      { number: 14, text: "Als aber Jesus es sah, wurde er unwillig und sprach zu ihnen: Lasst die Kinder zu mir kommen! Wehrt ihnen nicht! Denn solchen gehört das Reich* Gottes.", footnotes: ["o. die Königsherrschaft"] },
      { number: 15, text: "Wahrlich, ich sage euch: Wer das Reich* Gottes nicht annimmt wie ein Kind, wird dort nicht hineinkommen*.", footnotes: ["o. die Königsherrschaft", "℘ Mt 18,3"] },
      { number: 16, text: "Und er nahm sie in seine Arme*, legte die Hände auf sie und segnete sie.", footnotes: ["℘ Kap. 9,36"] },
      { number: 17, text: "*Und als er auf den Weg hinausging, lief einer herbei, fiel vor ihm auf die Knie und fragte ihn: Guter Lehrer, was soll ich tun, damit ich ewiges Leben erbe*?", heading: "Frage eines Reichen nach dem ewigen Leben", footnotes: ["℘ Mt 19,16-30; Lk 18,18-30", "℘ Lk 10,25 ⇨Esyn: Synopse Nr. 254"] },
      { number: 18, text: "Jesus aber sprach zu ihm: Was nennst du mich gut? Niemand ist gut als nur einer, Gott*.", footnotes: ["℘ Ps 86,5"] },
      { number: 19, text: "Die Gebote weißt du: »Du sollst nicht töten*; du sollst nicht ehebrechen*; du sollst nicht stehlen; du sollst nicht falsches Zeugnis reden; du sollst nichts vorenthalten; ehre deinen Vater und deine Mutter*!«", footnotes: ["℘ Mt 5,21.27", "℘ Kap. 3,9", "℘ Kap. 7,10; 2Mo 20,12-17; 5Mo 5,16-20"] },
      { number: 20, text: "Er aber sagte zu ihm: Lehrer, dies alles habe ich befolgt* von meiner Jugend an.", footnotes: ["o. beachtet, eingehalten"] },
      { number: 21, text: "Jesus aber blickte ihn an, gewann ihn lieb und sprach zu ihm: Eins fehlt dir. Geh hin, verkaufe alles, was du hast, und gib <den Erlös> den Armen, und du wirst einen Schatz im Himmel haben*, und komm, folge mir nach*!", footnotes: ["℘ Mt 6,20", "Andere Handschr. fügen hinzu: das Kreuz aufnehmend\n℘ Kap. 8,34"] },
      { number: 22, text: "Er aber ging, entsetzt* über das Wort, traurig weg, denn er hatte viele Güter*.", footnotes: ["o. niedergeschlagen, o. finster", "℘ Ps 62,11"] },
      { number: 23, text: "Und Jesus blickte umher und spricht zu seinen Jüngern: Wie schwer werden die, welche Güter haben, in das Reich* Gottes hineinkommen*!", footnotes: ["o. die Königsherrschaft", "℘ Kap. 4,19 ⇨Esyn: Synopse Nr. 255"] },
      { number: 24, text: "Die Jünger aber erschraken über seine Worte. Jesus aber antwortete wieder und spricht zu ihnen: Kinder, wie schwer ist es, in das Reich* Gottes hineinzukommen!*", footnotes: ["o. die Königsherrschaft", "℘ Spr 11,28; 1Tim 6,17"] },
      { number: 25, text: "Es ist leichter, dass ein Kamel durch das Öhr der Nadel geht, als dass ein Reicher in das Reich* Gottes hineinkommt.", footnotes: ["o. die Königsherrschaft"] },
      { number: 26, text: "Sie aber gerieten ganz außer sich und sprachen zueinander: Und wer kann <dann> gerettet werden?" },
      { number: 27, text: "Jesus aber sah sie an und spricht: Bei Menschen ist es unmöglich, aber nicht bei Gott; denn bei Gott sind alle Dinge möglich*. —", footnotes: ["℘ Mt 19,26"] },
      { number: 28, text: "Petrus begann und sagte zu ihm: Siehe, wir haben alles verlassen und sind dir nachgefolgt*.", footnotes: ["℘ Kap. 1,18.20"] },
      { number: 29, text: "Jesus sprach: Wahrlich, ich sage euch: Da ist niemand, der Haus oder Brüder oder Schwestern oder Mutter oder Vater oder Kinder oder Äcker verlassen hat um meinetwillen und um des Evangeliums willen," },
      { number: 30, text: "der nicht hundertfach empfängt, jetzt in dieser Zeit Häuser und Brüder und Schwestern und Mütter und Kinder und Äcker unter Verfolgungen* — und in dem kommenden Zeitalter* ewiges Leben*.", footnotes: ["℘ 2Tim 3,12", "griech. Äon", "℘ 1Tim 4,8"] },
      { number: 31, text: "Aber viele Erste werden Letzte und Letzte Erste sein*.", footnotes: ["℘ Mt 20,16"] },
      { number: 32, text: "*Sie waren aber auf dem Weg und gingen hinauf nach Jerusalem, und Jesus ging vor ihnen her; und sie erschraken. Die ihm aber nachfolgten, fürchteten sich*. Und er nahm wieder die Zwölf zu sich und fing an, ihnen zu sagen, was ihm widerfahren sollte:", heading: "Dritte Leidensankündigung", footnotes: ["℘ Mt 20,17-19; Lk 18,31-34", "℘ Kap. 9,32 ⇨Esyn: Synopse Nr. 262"] },
      { number: 33, text: "Siehe, wir gehen hinauf nach Jerusalem, und der Sohn des Menschen wird den Hohenpriestern* und den Schriftgelehrten überliefert werden; und sie werden ihn zum Tod verurteilen und werden ihn den Nationen überliefern*;", footnotes: ["s. Anm. zu Kap. 8,31", "℘ Kap. 14,41; 15,1"] },
      { number: 34, text: "und sie werden ihn verspotten und ihn anspeien und ihn geißeln und töten; und nach drei Tagen wird er auferstehen*.", footnotes: ["℘ Mt 16,21"] },
      { number: 35, text: "*Und es treten zu ihm Jakobus und Johannes, die Söhne des Zebedäus, und sagen zu ihm: Lehrer, wir wollen, dass du uns tust, um was wir dich bitten werden. *", heading: "Wahre Größe im Reich Gottes", footnotes: ["℘ Mt 20,20-28", "℘ ⇨Esyn: Synopse Nr. 263"] },
      { number: 36, text: "Er aber sprach zu ihnen: Was wollt ihr, dass ich euch tun soll*?", footnotes: ["℘ V. 51"] },
      { number: 37, text: "Sie aber sprachen zu ihm: Gib uns, dass wir einer zu deiner Rechten und einer zu deiner Linken sitzen in deiner Herrlichkeit!" },
      { number: 38, text: "Jesus aber sprach zu ihnen: Ihr wisst nicht, um was ihr bittet. Könnt ihr den Kelch trinken, den ich trinke*, oder mit der Taufe getauft werden, mit der ich getauft werde*?", footnotes: ["℘ Kap. 14,36", "℘ Lk 12,50"] },
      { number: 39, text: "Sie aber sprachen zu ihm: Wir können es. Jesus aber sprach zu ihnen: Den Kelch, den ich trinke, werdet ihr trinken, und mit der Taufe, mit der ich getauft werde, werdet ihr getauft werden*;", footnotes: ["℘ Apg 12,2"] },
      { number: 40, text: "aber das Sitzen zu meiner Rechten oder Linken zu vergeben, steht nicht bei mir, sondern <ist für die,> denen es bereitet ist." },
      { number: 41, text: "Und als die Zehn es hörten, fingen sie an, unwillig zu werden über Jakobus und Johannes." },
      { number: 42, text: "Und Jesus rief sie zu sich und spricht zu ihnen: Ihr wisst, dass die, welche als Regenten der Nationen gelten, sie beherrschen und ihre Großen Gewalt gegen sie üben*.", footnotes: ["℘ Lk 22,25"] },
      { number: 43, text: "So aber ist es nicht unter euch; sondern wer unter euch groß werden will, soll euer Diener sein*;", footnotes: ["℘ Kap. 9,35; Lk 22,26"] },
      { number: 44, text: "und wer von euch der Erste sein will, soll aller Sklave sein*.", footnotes: ["℘ Kap. 9,35; Lk 22,26"] },
      { number: 45, text: "Denn auch der Sohn des Menschen ist nicht gekommen, um bedient zu werden, sondern um zu dienen und sein Leben zu geben als Lösegeld für viele*.", footnotes: ["℘ Kap. 14,24 ⇨Esyn: Synopse Nr. 302"] },
      { number: 46, text: "*Und sie kommen nach Jericho. Und als er und seine Jünger und eine große Volksmenge aus Jericho hinausgingen, saß der Sohn des Timäus, Bartimäus, ein blinder Bettler, am Weg. *", heading: "Heilung des blinden Bartimäus", footnotes: ["℘ Mt 20,29-34; Lk 18,35-43; vgl. Kap. 8,22-26; Mt 9,27-31", "℘ ⇨Esyn: Synopse Nr. 264"] },
      { number: 47, text: "Und als er hörte, dass es Jesus, der Nazarener*, sei, fing er an zu schreien und zu sagen: Sohn Davids*, Jesus, erbarme dich meiner!", footnotes: ["℘ Mt 2,23", "℘ Kap. 12,35; Mt 1,1"] },
      { number: 48, text: "Und viele bedrohten ihn, dass er schweigen sollte; er aber schrie umso mehr: Sohn Davids, erbarme dich meiner!" },
      { number: 49, text: "Und Jesus blieb stehen und sagte: Ruft ihn! Und sie rufen den Blinden und sagen zu ihm: Sei guten Mutes! Steh auf, er ruft dich*!", footnotes: ["℘ Joh 11,28"] },
      { number: 50, text: "Er aber warf sein Gewand ab, sprang auf und kam zu Jesus." },
      { number: 51, text: "Und Jesus antwortete ihm und sprach: Was willst du, dass ich dir tun soll*? Der Blinde aber sprach zu ihm: Rabbuni*, dass ich sehend werde.", footnotes: ["℘ V. 36", "Ausdruck gesteigerter Ehrerbietung für die Anredeform Rabbi; vgl. Anm. zu Kap. 9,5"] },
      { number: 52, text: "Und Jesus sprach zu ihm: Geh hin, dein Glaube hat dich geheilt*! Und sogleich wurde er sehend* und folgte ihm auf dem Weg nach.", footnotes: ["w. gerettet\n℘ Kap. 5,34", "℘ Ps 146,8; Jes 42,7; Joh 9,7"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "*Und als sie sich Jerusalem, Betfage und Betanien gegen den Ölberg hin nähern, sendet er zwei seiner Jünger*", heading: "Einzug in Jerusalem", footnotes: ["℘ Mt 21,1-11; Lk 19,28-44; Joh 12,12-19", "℘ Kap. 14,13 ⇨Esyn: Synopse Nr. 269"] },
      { number: 2, text: "und spricht zu ihnen: Geht in das Dorf, das euch gegenüberliegt! Und sogleich, wenn ihr dort hineinkommt, werdet ihr ein Fohlen angebunden finden, auf dem noch kein Mensch gesessen hat. Bindet es los und führt es her!" },
      { number: 3, text: "Und wenn jemand zu euch sagt: Warum tut ihr dies?, so sagt: Der Herr braucht es und sendet es gleich wieder hierher." },
      { number: 4, text: "Und sie gingen hin und fanden ein Fohlen angebunden an der Tür draußen auf dem Weg, und sie binden es los." },
      { number: 5, text: "Und einige von denen, die dort standen, sagten zu ihnen: Was tut ihr, dass ihr das Fohlen losbindet?" },
      { number: 6, text: "Sie aber sprachen zu ihnen, wie Jesus gesagt hatte. Und sie ließen sie <gewähren>." },
      { number: 7, text: "Und sie bringen das Fohlen zu Jesus und legen ihm ihre Kleider auf, und er setzte sich darauf*.", footnotes: ["℘ Sach 9,9"] },
      { number: 8, text: "Und viele breiteten ihre Kleider auf dem Weg aus, andere aber Zweige, die sie auf den Feldern abschnitten*;", footnotes: ["℘ 2Kö 9,13"] },
      { number: 9, text: "und die Vorangehenden und die Nachfolgenden riefen: Hosanna!* Gepriesen <sei>, der da kommt im Namen des Herrn*!", footnotes: ["griech. Form des hebr.-aram. Ausdrucks für »Hilf doch <Herr>!«", "℘ Ps 118,26"] },
      { number: 10, text: "Gepriesen sei das kommende Reich* unseres Vaters David*! Hosanna in der Höhe*!", footnotes: ["o. die kommende Königsherrschaft", "℘ Jer 33,15", "℘ Lk 2,14"] },
      { number: 11, text: "Und er zog in Jerusalem ein, in den Tempel*. Und als er über alles umhergeblickt hatte, ging er, da es schon spät an der Zeit war, mit den Zwölfen nach Betanien hinaus*.", footnotes: ["℘ Mal 3,1", "℘ V. 19; Mt 21,17 ⇨Esyn: Synopse Nr. 271"] },
      { number: 12, text: "*Und als sie am folgenden Tag von Betanien weggegangen waren, hungerte ihn. *", heading: "Verfluchung des Feigenbaumes", footnotes: ["℘ Mt 21,18.19", "℘ ⇨Esyn: Synopse Nr. 272"] },
      { number: 13, text: "Und er sah von weitem einen Feigenbaum, der Blätter hatte, und er ging hin, ob er wohl etwas an ihm fände; und als er zu ihm kam, fand er nichts als Blätter, denn es war nicht die Zeit der Feigen*.", footnotes: ["℘ Lk 13,6"] },
      { number: 14, text: "Und er begann* und sprach zu ihm: Nie mehr in Ewigkeit* soll jemand Frucht von dir essen*! Und seine Jünger hörten es.", footnotes: ["w. antwortete; hier in semitisierender Redeweise für den Anfang einer Rede gebraucht", "griech. Äon", "℘ V. 20"] },
      { number: 15, text: "*Und sie kommen nach Jerusalem. Und er trat in den Tempel und begann die hinauszutreiben, die im Tempel verkauften und kauften; und die Tische der Wechsler und die Sitze der Taubenverkäufer stieß er um. *", heading: "Tempelreinigung", footnotes: ["℘ Mt 21,12-17; Lk 19,45-48; vgl. Joh 2,13-17", "℘ ⇨Esyn: Synopse Nr. 273"] },
      { number: 16, text: "Und er erlaubte nicht, dass jemand ein Gerät durch den Tempel trug." },
      { number: 17, text: "Und er lehrte und sprach zu ihnen: Steht nicht geschrieben: »Mein Haus wird ein Bethaus genannt werden für alle Nationen«?* Ihr aber habt es zu einer »Räuberhöhle«* gemacht.", footnotes: ["℘ Jes 56,7", "℘ Jer 7,11"] },
      { number: 18, text: "Und die Hohenpriester und die Schriftgelehrten hörten es und suchten, wie sie ihn umbringen könnten*; sie fürchteten ihn nämlich, denn die ganze Volksmenge geriet außer sich über seine Lehre*.", footnotes: ["℘ Kap. 12,12", "℘ Kap. 1,22 ⇨Esyn: Synopse Nr. 305"] },
      { number: 19, text: "Und wenn es Abend wurde, gingen sie zur Stadt hinaus*.", footnotes: ["℘ V. 11"] },
      { number: 20, text: "*Und als sie frühmorgens vorbeigingen, sahen sie den Feigenbaum verdorrt von den Wurzeln an*.", heading: "Das Gebet im Glauben und in Vergebungsbereitschaft", footnotes: ["℘ Mt 21,20-22", "℘ V. 14 ⇨Esyn: Synopse Nr. 275"] },
      { number: 21, text: "Und Petrus erinnerte sich und spricht zu ihm: Rabbi*, siehe, der Feigenbaum, den du verflucht hast, ist verdorrt.", footnotes: ["d. h. Mein Meister!; respektvolle Anrede der geistlichen Lehrer im Spätjudentum"] },
      { number: 22, text: "Und Jesus antwortete und spricht zu ihnen: Habt Glauben an Gott*! *", footnotes: ["o. Habt Gottes Glauben", "℘ ⇨Esyn: Synopse Nr. 231"] },
      { number: 23, text: "Wahrlich, ich sage euch: Wer zu diesem Berg sagen wird: Hebe dich empor und wirf dich ins Meer!, und nicht zweifeln wird in seinem Herzen, sondern glauben, dass geschieht, was er sagt, dem wird es werden*.", footnotes: ["℘ Kap. 5,36"] },
      { number: 24, text: "Darum sage ich euch: Alles, um was ihr auch betet und bittet, glaubt, dass ihr es empfangen habt, und es wird euch werden*.", footnotes: ["℘ Joh 14,13; Jak 5,15"] },
      { number: 25, text: "Und wenn ihr steht und betet, so vergebt, wenn ihr etwas gegen jemand habt*, damit auch euer Vater, der in den Himmeln ist, euch eure Übertretungen vergebe*.", footnotes: ["℘ Mt 5,23", "℘ Lk 11,4"] },
      { number: 26, text: "[T>]*", footnotes: ["Andere Handschr. fügen hinzu: Wenn ihr aber nicht vergebt, so wird euer Vater, der in den Himmeln ist, auch eure Übertretungen nicht vergeben.\n℘ Mt 6,14.15; 18,35"] },
      { number: 27, text: "*Und sie kommen wieder nach Jerusalem. Und als er in dem Tempel umherging, kommen die Hohenpriester und die Schriftgelehrten und die Ältesten zu ihm *", heading: "Die Frage nach der Vollmacht Jesu", footnotes: ["℘ Mt 21,23-27; Lk 20,1-8", "℘ ⇨Esyn: Synopse Nr. 276"] },
      { number: 28, text: "und sagen zu ihm: In welcher Vollmacht tust du diese Dinge? Oder wer hat dir diese Vollmacht gegeben, dass du diese Dinge tust*?", footnotes: ["℘ Joh 2,18"] },
      { number: 29, text: "Jesus aber sprach zu ihnen: Ich will euch ein Wort fragen. Antwortet mir! Und ich werde euch sagen, in welcher Vollmacht ich diese Dinge tue:" },
      { number: 30, text: "War die Taufe des Johannes vom Himmel oder von Menschen? Antwortet mir!" },
      { number: 31, text: "Und sie überlegten miteinander und sprachen: Wenn wir sagen: vom Himmel, so wird er sagen: Warum habt ihr ihm denn nicht geglaubt*?", footnotes: ["℘ Mt 21,32"] },
      { number: 32, text: "Sollen wir aber sagen: von Menschen? Sie fürchteten die Volksmenge. Denn alle meinten, dass Johannes wirklich ein Prophet sei*.", footnotes: ["℘ Mt 14,5"] },
      { number: 33, text: "Und sie antworten und sagen zu Jesus: Wir wissen es nicht. Und Jesus spricht zu ihnen: So sage auch ich euch nicht, in welcher Vollmacht ich diese Dinge tue." },
    ]},
    { number: 12, verses: [
      { number: 1, text: "*Und er fing an, in Gleichnissen zu ihnen zu reden*: Ein Mensch pflanzte einen Weinberg und setzte einen Zaun darum und grub einen Keltertrog und baute einen Turm*; und er verpachtete ihn an Weingärtner und reiste außer Landes.", heading: "Gleichnis von den Weingärtnern", footnotes: ["℘ Mt 21,33-46; Lk 20,9-19", "℘ Kap. 4,33.34", "℘ Jes 5,2 ⇨Esyn: Synopse Nr. 278"] },
      { number: 2, text: "Und er sandte zur bestimmten Zeit zu den Weingärtnern einen Knecht*, um von den Weingärtnern <etwas> von den Früchten des Weinbergs zu empfangen.", footnotes: ["w. Sklaven"] },
      { number: 3, text: "Sie aber nahmen ihn, schlugen ihn und sandten ihn leer fort*.", footnotes: ["℘ 1Kö 19,10; 2Chr 36,16; Jer 2,30; Mt 23,37"] },
      { number: 4, text: "Und wieder sandte er einen anderen Knecht* zu ihnen; und den verwundeten sie am Kopf und beschimpften ihn*.", footnotes: ["w. Sklaven", "℘ 1Kö 19,10; 2Chr 36,16; Jer 2,30; Mt 23,37"] },
      { number: 5, text: "Und er sandte einen anderen, und den töteten sie; und viele andere; die einen schlugen sie, die anderen töteten sie*.", footnotes: ["℘ 1Kö 19,10; 2Chr 36,16; Jer 2,30; Mt 23,37"] },
      { number: 6, text: "Noch einen hatte er, einen geliebten Sohn*, den sandte er als Letzten zu ihnen, indem er sprach: Sie werden sich vor meinem Sohn scheuen.", footnotes: ["℘ Kap. 9,7"] },
      { number: 7, text: "Jene Weingärtner aber sprachen zueinander: Dies ist der Erbe*; kommt, lasst uns ihn töten, und das Erbe wird unser sein.", footnotes: ["℘ Hebr 1,1.2"] },
      { number: 8, text: "Und sie nahmen und töteten ihn und warfen ihn zum Weinberg hinaus*.", footnotes: ["℘ Joh 1,11"] },
      { number: 9, text: "Was wird der Herr des Weinbergs tun? Er wird kommen und die Weingärtner umbringen und den Weinberg anderen geben." },
      { number: 10, text: "Habt ihr nicht auch diese Schrift gelesen: »Der Stein, den die Bauleute verworfen haben, der ist zum Eckstein* geworden*;", footnotes: ["w. zum Haupt der Ecke", "℘ Eph 2,20"] },
      { number: 11, text: "vom Herrn her ist er dies geworden, und er ist wunderbar in unseren Augen*«?", footnotes: ["℘ Ps 118,22.23"] },
      { number: 12, text: "Und sie suchten ihn zu greifen und fürchteten die Volksmenge; denn sie erkannten, dass er das Gleichnis auf sie hin gesprochen hatte*. Und sie ließen ihn und gingen davon.", footnotes: ["℘ Jes 5,7"] },
      { number: 13, text: "*Und sie senden einige der Pharisäer* und der Herodianer* zu ihm, um ihn in der Rede zu fangen*.", heading: "Die Frage nach der Steuer", footnotes: ["℘ Mt 22,15-22; Lk 20,20-26", "religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; vgl. Anm. zu Mt 3,7", "Anhänger des Herodes Antipas; s. Anm. zu Mt 14,1", "℘ Kap. 3,2.6; Jes 29,21 ⇨Esyn: Synopse Nr. 280"] },
      { number: 14, text: "Und sie kommen und sagen zu ihm: Lehrer, wir wissen, dass du wahrhaftig bist und dich um niemand kümmerst; denn du siehst nicht auf die Person der Menschen*, sondern lehrst den Weg Gottes in Wahrheit. Ist es erlaubt, dem Kaiser Steuer zu geben oder nicht? Sollen wir sie geben oder nicht geben?", footnotes: ["℘ Apg 10,34"] },
      { number: 15, text: "Da er aber ihre Heuchelei kannte*, sprach er zu ihnen: Was versucht ihr mich? Bringt mir einen Denar, damit ich ihn sehe!", footnotes: ["℘ Spr 26,24"] },
      { number: 16, text: "Sie aber brachten ihn. Und er spricht zu ihnen: Wessen ist dieses Bild und die Aufschrift? Sie aber sagten zu ihm: Des Kaisers." },
      { number: 17, text: "Jesus aber sprach zu ihnen: Gebt dem Kaiser, was des Kaisers ist*, und Gott, was Gottes ist! Und sie verwunderten sich über ihn.", footnotes: ["℘ Röm 13,7"] },
      { number: 18, text: "*Und es kommen Sadduzäer* zu ihm, die sagen, es gebe keine Auferstehung*; und sie fragten ihn und sprachen:", heading: "Die Frage nach der Auferstehung", footnotes: ["℘ Mt 22,23-33; Lk 20,27-40", "religiöse Partei, der u. a. die vornehmen Priesterfamilien angehörten; s. auch Anm. zu Mt 3,7", "℘ Apg 23,8 ⇨Esyn: Synopse Nr. 281"] },
      { number: 19, text: "Lehrer, Mose hat uns geschrieben: Wenn jemandes Bruder stirbt und lässt eine Frau zurück und hinterlässt kein Kind, dass sein Bruder seine Frau nehme und seinem Bruder Nachkommenschaft* erwecke*.", footnotes: ["w. Samen", "℘ 5Mo 25,5.6"] },
      { number: 20, text: "Es waren sieben Brüder. Und der erste nahm eine Frau; und als er starb, hinterließ er keine Nachkommenschaft*;", footnotes: ["w. Samen"] },
      { number: 21, text: "und der zweite nahm sie und starb und ließ keine Nachkommenschaft* zurück; und der dritte ebenso.", footnotes: ["w. Samen"] },
      { number: 22, text: "Und die sieben hinterließen keine Nachkommenschaft*. Zuletzt von allen starb auch die Frau.", footnotes: ["w. Samen"] },
      { number: 23, text: "Wessen Frau von allen wird sie in der Auferstehung sein, wenn sie auferstehen werden? Denn die sieben haben sie zur Frau gehabt." },
      { number: 24, text: "Jesus sprach zu ihnen: Irrt ihr nicht deshalb, weil ihr die Schriften nicht kennt und nicht die Kraft Gottes?" },
      { number: 25, text: "Denn wenn sie aus den Toten auferstehen, heiraten sie nicht, noch werden sie verheiratet, sondern sie sind wie Engel in den Himmeln." },
      { number: 26, text: "Was aber die Toten betrifft, dass sie auferweckt werden: Habt ihr nicht im Buch Moses gelesen, wie Gott beim Dornbusch zu ihm redete und sprach: »Ich bin der Gott Abrahams und der Gott Isaaks und der Gott Jakobs«*?", footnotes: ["℘ 2Mo 3,2.6"] },
      { number: 27, text: "Er ist nicht der Gott von Toten, sondern von Lebenden. Ihr irrt sehr." },
      { number: 28, text: "*Und einer der Schriftgelehrten, der gehört hatte, wie sie miteinander stritten, trat hinzu, und da er wusste, dass er ihnen gut geantwortet hatte, fragte er ihn: Welches Gebot ist das erste von allen? *", heading: "Die Frage nach dem ersten Gebot", footnotes: ["℘ Mt 22,34-40; vgl. Lk 10,25-28", "℘ ⇨Esyn: Synopse Nr. 282"] },
      { number: 29, text: "Jesus antwortete ihm: Das erste ist: »Höre, Israel: Der Herr, unser Gott, ist ein Herr;" },
      { number: 30, text: "und du sollst den Herrn, deinen Gott, lieben aus deinem ganzen Herzen und aus deiner ganzen Seele und aus deinem ganzen Verstand und aus deiner ganzen Kraft!«*", footnotes: ["℘ 5Mo 6,4.5; 10,12"] },
      { number: 31, text: "Das zweite ist dies: »Du sollst deinen Nächsten lieben wie dich selbst!«* Größer als diese ist kein anderes Gebot.", footnotes: ["℘ 3Mo 19,18"] },
      { number: 32, text: "Und der Schriftgelehrte sprach zu ihm: Recht, Lehrer, du hast nach der Wahrheit geredet; denn er ist einer, und es ist kein anderer außer ihm*;", footnotes: ["℘ 5Mo 4,35.39; Jes 45,5.6; 1Kor 8,4"] },
      { number: 33, text: "und ihn zu lieben aus ganzem Herzen und aus ganzem Verständnis und aus ganzer Seele und aus ganzer Kraft und den Nächsten zu lieben wie sich selbst, ist viel mehr als alle Brandopfer und Schlachtopfer*.", footnotes: ["℘ 1Sam 15,22; Hos 6,6; Mi 6,6-8"] },
      { number: 34, text: "Und als Jesus sah, dass er verständig geantwortet hatte, sprach er zu ihm: Du bist nicht fern vom Reich* Gottes. Und es wagte niemand mehr, ihn zu befragen*.", footnotes: ["o. von der Königsherrschaft", "℘ Mt 22,46"] },
      { number: 35, text: "*Und Jesus begann* und sprach, als er im Tempel lehrte: Wie sagen die Schriftgelehrten, dass der Christus Davids Sohn sei*?", heading: "Die Frage nach dem Christus", footnotes: ["℘ Mt 22,41-46; Lk 20,41-44", "w. antwortete; hier in semitisierender Redeweise für den Anfang einer Rede gebraucht", "℘ Joh 7,42 ⇨Esyn: Synopse Nr. 283"] },
      { number: 36, text: "David selbst hat im Heiligen Geist* gesagt: »Der Herr sprach zu meinem Herrn: Setze dich zu meiner Rechten*, bis ich deine Feinde unter deine Füße lege!«*", footnotes: ["℘ Hebr 10,15; 1Petr 1,11", "℘ Kap. 14,62; 16,19", "℘ Ps 110,1"] },
      { number: 37, text: "David selbst nennt ihn Herr. Und woher ist er sein Sohn? Und die große Volksmenge hörte ihn gern*.", footnotes: ["℘ Lk 19,48 ⇨Esyn: Synopse Nr. 284"] },
      { number: 38, text: "*Und er sprach in seiner Lehre: Hütet euch vor den Schriftgelehrten, die in langen Gewändern einhergehen wollen und die Begrüßungen auf den Märkten", heading: "Warnung vor den Schriftgelehrten", footnotes: ["℘ Mt 23,5-7; Lk 20,45-47"] },
      { number: 39, text: "und die ersten Sitze in den Synagogen und die ersten Plätze bei den Gastmählern* <lieben>;", footnotes: ["s. Anm. zu Mt 23,6"] },
      { number: 40, text: "die die Häuser der Witwen verschlingen und zum Schein lange Gebete halten*! Sie werden ein schwereres Gericht empfangen*.", footnotes: ["℘ Mt 6,7", "℘ Jak 3,1 ⇨Esyn: Synopse Nr. 294"] },
      { number: 41, text: "*Und er setzte sich dem Schatzkasten* gegenüber und sah, wie die Volksmenge Geld in den Schatzkasten einlegte. Und viele Reiche legten viel ein.", heading: "Die Gabe der armen Witwe", footnotes: ["℘ Lk 21,1-4", "℘ 2Kö 12,10 ⇨Esyn: Synopse Nr. 286"] },
      { number: 42, text: "Und eine arme Witwe kam und legte zwei Scherflein* ein, das ist ein Cent*.", footnotes: ["w. Lepta; s. Tabelle »Münzen und Geldeinheiten«", "w. Quadrans; s. Tabelle »Münzen und Geldeinheiten«"] },
      { number: 43, text: "Und er rief seine Jünger herbei und sprach zu ihnen: Wahrlich, ich sage euch: Diese arme Witwe hat mehr eingelegt als alle, die in den Schatzkasten eingelegt haben*.", footnotes: ["℘ 2Kor 8,12"] },
      { number: 44, text: "Denn alle haben von ihrem Überfluss eingelegt; diese aber hat aus ihrem Mangel alles, was sie hatte, eingelegt, ihren ganzen Lebensunterhalt." },
    ]},
    { number: 13, verses: [
      { number: 1, text: "*Und als er aus dem Tempel heraustrat, sagt einer seiner Jünger zu ihm: Lehrer, sieh, was für Steine und was für Gebäude! *", heading: "Endzeitrede: Tempelzerstörung und Drangsale der Endzeit", footnotes: ["℘ Mt 24,1-14; Lk 21,5-19", "℘ ⇨Esyn: Synopse Nr. 287"] },
      { number: 2, text: "Und Jesus sprach zu ihm: Siehst du diese großen Gebäude? Hier wird nicht ein Stein auf dem anderen* gelassen werden, der nicht abgebrochen werden wird*.", footnotes: ["w. Stein auf Stein", "℘ Lk 19,44"] },
      { number: 3, text: "Und als er auf dem Ölberg dem Tempel gegenübersaß, fragten ihn Petrus und Jakobus und Johannes und Andreas für sich allein: *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 288"] },
      { number: 4, text: "Sage uns, wann wird das sein, und was ist das Zeichen, wann dies alles vollendet werden soll?" },
      { number: 5, text: "Jesus aber begann zu ihnen zu sprechen: Seht zu, dass euch niemand verführe*!", footnotes: ["℘ Jer 29,8; Eph 5,6 ⇨Esyn: Synopse Nr. 291"] },
      { number: 6, text: "Viele werden unter meinem Namen kommen und sagen: Ich bin's! Und sie werden viele verführen*.", footnotes: ["℘ V. 22"] },
      { number: 7, text: "Wenn ihr aber von Kriegen und Kriegsgerüchten hören werdet, so erschreckt nicht! Es muss geschehen, aber es ist noch nicht das Ende." },
      { number: 8, text: "Denn es wird sich Nation gegen Nation und Königreich gegen Königreich erheben*; es werden Erdbeben sein an verschiedenen Orten, es werden Hungersnöte* sein. Dies ist der Anfang der Wehen.", footnotes: ["℘ 2Chr 15,6; Jes 19,2; Hag 2,22; Offb 6,4", "℘ Offb 6,6; Mt 10,17-22"] },
      { number: 9, text: "*Ihr aber, seht auf euch selbst! Euch werden sie an Gerichte* überliefern, und in den Synagogen werdet ihr geschlagen werden*, und ihr werdet vor Statthalter und Könige gestellt werden um meinetwillen, ihnen zu einem Zeugnis*;", footnotes: ["℘ Mt 10,17-22", "w. Synedrien", "Gemeint ist die Strafe der Geißelung; vgl. Anm. zu Mt 10,17.", "℘ Apg 5,40; 26,11 ⇨Esyn: Synopse Nr. 289"] },
      { number: 10, text: "und allen Nationen muss vorher das Evangelium gepredigt werden*.", footnotes: ["℘ Kap. 16,15"] },
      { number: 11, text: "Und wenn sie euch hinführen, um euch zu überliefern, so sorgt euch vorher nicht, was ihr reden sollt, sondern was euch in jener Stunde gegeben wird, das redet! Denn nicht ihr seid die Redenden, sondern der Heilige Geist*.", footnotes: ["℘ Lk 12,11.12"] },
      { number: 12, text: "Und es wird der Bruder den Bruder zum Tod überliefern und der Vater das Kind; und Kinder werden sich gegen Eltern erheben und sie zu Tode bringen*.", footnotes: ["℘ Mi 7,6; Lk 12,53"] },
      { number: 13, text: "Und ihr werdet von allen gehasst werden um meines Namens willen; wer aber ausharrt bis ans Ende, der wird gerettet werden." },
      { number: 14, text: "*Wenn ihr aber den Gräuel der Verwüstung stehen seht, wo er nicht sollte* — wer es liest, merke auf! —, dann sollen die in Judäa auf die Berge fliehen;", footnotes: ["℘ Mt 24,15-25; Lk 21,20-23", "℘ Dan 9,27 ⇨Esyn: Synopse Nr. 290"] },
      { number: 15, text: "wer auf dem Dach ist, soll nicht hinabsteigen und nicht hineingehen, um etwas aus seinem Haus zu holen;" },
      { number: 16, text: "und wer auf dem Feld ist, soll nicht zurückkehren, um seinen Mantel zu holen*.", footnotes: ["℘ Lk 17,31"] },
      { number: 17, text: "Wehe aber den Schwangeren und den Stillenden in jenen Tagen!" },
      { number: 18, text: "Betet aber, dass es nicht im Winter geschehe!" },
      { number: 19, text: "Denn jene Tage werden eine Bedrängnis sein, wie sie von Anfang der Schöpfung, die Gott geschaffen hat, bis jetzt nicht gewesen ist und nicht sein wird*.", footnotes: ["℘ Dan 12,1; Joe 2,2; Offb 16,18"] },
      { number: 20, text: "Und wenn nicht der Herr die Tage verkürzt hätte, würde kein Fleisch gerettet werden; aber um der Auserwählten willen, die er auserwählt hat, hat er die Tage verkürzt*.", footnotes: ["℘ Jes 65,8; Röm 9,27.28"] },
      { number: 21, text: "Und wenn dann jemand zu euch sagt: Siehe, hier ist der Christus! Siehe dort!, so glaubt nicht*!", footnotes: ["℘ Lk 17,23 ⇨Esyn: Synopse Nr. 291"] },
      { number: 22, text: "Es werden aber falsche Christusse und falsche Propheten aufstehen und werden Zeichen und Wunder tun, um, wenn möglich, die Auserwählten zu verführen*.", footnotes: ["℘ V. 6; Mt 7,15 ⇨Esyn: Synopse Nr. 289"] },
      { number: 23, text: "Ihr aber, seht zu! Ich habe euch alles vorhergesagt*.", footnotes: ["℘ 2Petr 3,17"] },
      { number: 24, text: "*Aber in jenen Tagen, nach jener Bedrängnis, wird die Sonne verfinstert werden und der Mond seinen Schein nicht geben*;", heading: "Endzeitrede: Ankunft des Menschensohnes", footnotes: ["℘ Mt 24,29-31; Lk 21,25-28", "℘ Joe 2,2.10; 3,3.4; Apg 2,20 ⇨Esyn: Synopse Nr. 292"] },
      { number: 25, text: "und die Sterne werden vom Himmel herabfallen, und die Kräfte in den Himmeln werden erschüttert werden*.", footnotes: ["℘ Jes 34,4"] },
      { number: 26, text: "Und dann werden sie den Sohn des Menschen kommen sehen in Wolken mit großer Macht und Herrlichkeit*.", footnotes: ["℘ Kap. 14,62"] },
      { number: 27, text: "Und dann wird er die Engel aussenden* und seine Auserwählten versammeln von den vier Winden her, vom Ende der Erde bis zum Ende des Himmels*.", footnotes: ["℘ Mt 13,41", "℘ Jes 43,5.6"] },
      { number: 28, text: "*Von dem Feigenbaum aber lernt das Gleichnis: Wenn sein Zweig schon weich* geworden ist und die Blätter hervortreibt, erkennt ihr, dass der Sommer nahe ist. *", heading: "Endzeitrede: Ermahnung zur Wachsamkeit", footnotes: ["℘ Mt 24,32-44; Lk 21,29-36", "o. zart; o. saftig", "℘ ⇨Esyn: Synopse Nr. 293"] },
      { number: 29, text: "So sollt auch ihr, wenn ihr dies geschehen seht, erkennen, dass es nahe vor der Tür ist." },
      { number: 30, text: "Wahrlich, ich sage euch: Dieses Geschlecht wird nicht vergehen, bis alles dies geschehen ist*.", footnotes: ["℘ Mt 23,36"] },
      { number: 31, text: "Der Himmel und die Erde werden vergehen, meine Worte aber werden nicht vergehen*.", footnotes: ["℘ Mt 5,18 ⇨Esyn: Synopse Nr. 226"] },
      { number: 32, text: "Von jenem Tag aber oder der Stunde weiß niemand, auch nicht die Engel im Himmel, auch nicht der Sohn, sondern nur der Vater*.", footnotes: ["℘ Apg 1,7"] },
      { number: 33, text: "Seht zu, wacht! Denn ihr wisst nicht, wann die Zeit ist*.", footnotes: ["℘ Kap. 14,38; Mt 24,50 ⇨Esyn: Synopse Nr. 295"] },
      { number: 34, text: "Wie ein Mensch, der außer Landes reiste*, sein Haus verließ und seinen Knechten* die Vollmacht gab, einem jeden sein Werk, und dem Türhüter einschärfte, dass er wache,", footnotes: ["℘ Mt 21,33; Lk 19,12", "w. Sklaven"] },
      { number: 35, text: "so wacht nun! Denn ihr wisst nicht, wann der Herr des Hauses kommt, ob des Abends oder um Mitternacht oder um den Hahnenschrei oder frühmorgens*,", footnotes: ["In neutestamentl. Zeit galt die griech.-röm. Einteilung der Nacht in vier Nachtwachen (Abend/Mitternacht/Hahnenschrei/Morgen) zu je drei Stunden.\n℘ Lk 12,38"] },
      { number: 36, text: "damit er nicht, wenn er plötzlich kommt, euch schlafend finde*.", footnotes: ["℘ Mt 25,5; Röm 13,11"] },
      { number: 37, text: "Was ich aber euch sage, sage ich allen: Wacht*!", footnotes: ["℘ Lk 12,37; 1Petr 5,8"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "*Es war aber nach zwei Tagen* das Passah und <das Fest der> ungesäuerten Brote*. Und die Hohenpriester* und die Schriftgelehrten suchten, wie sie ihn mit List greifen und töten könnten*;", heading: "Anschlag der Hohenpriester", footnotes: ["℘ Mt 26,1-5; Lk 22,1.2", "d. h. in zwei Tagen", "℘ 3Mo 23,5.6", "Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet.", "℘ Joh 11,53 ⇨Esyn: Synopse Nr. 305"] },
      { number: 2, text: "denn sie sagten: Nicht an dem Fest, damit nicht etwa ein Aufruhr des Volkes entsteht." },
      { number: 3, text: "*Und als er in Betanien war, in dem Hause Simons des Aussätzigen, kam, während er zu Tisch lag, eine Frau, die ein Alabasterfläschchen mit Salböl von echter, kostbarer Narde* hatte; sie zerbrach das Fläschchen und goss es aus auf sein Haupt. *", heading: "Salbung Jesu in Betanien", footnotes: ["℘ Mt 26,6-13; Joh 12,1-8", "Pflanze, die zur Herstellung von Arzneien, Salben und Ölen diente; als Importartikel aus Indien sehr teuer", "℘ ⇨Esyn: Synopse Nr. 306"] },
      { number: 4, text: "Es waren aber einige bei sich selbst unwillig: Wozu ist diese Verschwendung des Salböls geschehen?" },
      { number: 5, text: "Denn dieses Salböl hätte für mehr als dreihundert Denare verkauft und den Armen gegeben werden können. Und sie fuhren sie an." },
      { number: 6, text: "Jesus aber sprach: Lasst sie! Was macht ihr ihr Mühe? Sie hat ein gutes Werk an mir getan;" },
      { number: 7, text: "denn die Armen habt ihr allezeit bei euch*, und wenn ihr wollt, könnt ihr ihnen wohltun; mich aber habt ihr nicht allezeit.", footnotes: ["℘ 5Mo 15,11"] },
      { number: 8, text: "Sie hat getan, was sie konnte; sie hat im Voraus meinen Leib zum Begräbnis gesalbt." },
      { number: 9, text: "Aber wahrlich, ich sage euch: Wo das Evangelium gepredigt werden wird in der ganzen Welt, wird auch von dem, was sie getan hat, geredet werden zu ihrem Gedächtnis." },
      { number: 10, text: "*Und Judas Iskariot*, einer von den Zwölfen, ging zu den Hohenpriestern hin, um ihn an sie zu überliefern*.", heading: "Verrat des Judas", footnotes: ["℘ Mt 26,14-16; Lk 22,3-6", "s. Anm. zu Mt 26,14", "℘ Joh 6,71 ⇨Esyn: Synopse Nr. 307"] },
      { number: 11, text: "Sie aber freuten sich, als sie es hörten, und versprachen, ihm Geld zu geben; und er suchte, wie er ihn zu gelegener Zeit überliefern könnte*.", footnotes: ["℘ Joh 13,2"] },
      { number: 12, text: "*Und am ersten Tag <des Festes> der ungesäuerten Brote, als man das Passah<lamm> schlachtete*, sagen seine Jünger zu ihm: Wohin willst du, dass wir gehen und bereiten, damit du das Passah<mahl> essen kannst?", heading: "Vorbereitung des Passahmahles", footnotes: ["℘ Mt 26,17-19; Lk 22,7-13", "℘ 2Mo 12,11 ⇨Esyn: Synopse Nr. 308"] },
      { number: 13, text: "Und er sendet zwei seiner Jünger* und spricht zu ihnen: Geht hin in die Stadt, und es wird euch ein Mensch begegnen, der einen Krug Wasser trägt. Folgt ihm!", footnotes: ["℘ Kap. 11,1"] },
      { number: 14, text: "Und wo er hineingeht, sprecht zu dem Hausherrn: Der Lehrer sagt: Wo ist mein Gastzimmer, wo ich mit meinen Jüngern das Passah<mahl> essen kann?" },
      { number: 15, text: "Und er wird euch einen großen Obersaal zeigen, <mit Polstern> ausgelegt* und fertig. Und dort bereitet es für uns!", footnotes: ["o. gedielt; o. getäfelt"] },
      { number: 16, text: "Und die Jünger gingen hinaus und kamen in die Stadt und fanden es, wie er ihnen gesagt hatte; und sie bereiteten das Passah<mahl>." },
      { number: 17, text: "*Und als es Abend geworden war, kommt er mit den Zwölfen.", heading: "Bezeichnung des Verräters", footnotes: ["℘ Mt 26,20-25; Lk 22,14.21-23; Joh 13,18-30"] },
      { number: 18, text: "Und während sie zu Tisch lagen und aßen, sprach Jesus: Wahrlich, ich sage euch: Einer von euch wird mich überliefern, der, welcher mit mir isst*.", footnotes: ["℘ Ps 41,10 ⇨Esyn: Synopse Nr. 310"] },
      { number: 19, text: "Sie fingen an, betrübt zu werden und einer nach dem anderen zu ihm zu sagen: Doch nicht ich?" },
      { number: 20, text: "Er aber sprach zu ihnen: Einer von den Zwölfen, der mit mir <das Brot> in die Schüssel eintaucht." },
      { number: 21, text: "Der Sohn des Menschen geht zwar dahin, wie über ihn geschrieben steht*. Wehe aber jenem Menschen, durch den der Sohn des Menschen überliefert wird! Es wäre jenem Menschen gut, wenn er nicht geboren wäre*.", footnotes: ["℘ V. 49; Jes 53,7", "℘ Joh 17,12"] },
      { number: 22, text: "*Und während sie aßen, nahm er Brot, segnete, brach und gab es ihnen und sprach: Nehmt, dies ist mein Leib! *", heading: "Einsetzung des Herrenmahles", footnotes: ["℘ Mt 26,26-30; Lk 22,15-20; 1Kor 11,23-25", "℘ ⇨Esyn: Synopse Nr. 311"] },
      { number: 23, text: "Und er nahm einen Kelch, dankte und gab ihnen <den>; und sie tranken alle daraus." },
      { number: 24, text: "Und er sprach zu ihnen: Dies ist mein Blut des Bundes*, das für viele vergossen wird*.", footnotes: ["℘ Hebr 12,24", "℘ Kap. 10,45"] },
      { number: 25, text: "Wahrlich, ich sage euch, dass ich nicht mehr von dem Gewächs des Weinstocks trinken werde bis zu jenem Tag, da ich es neu trinken werde im Reich* Gottes.", footnotes: ["o. in der Königsherrschaft"] },
      { number: 26, text: "Und als sie ein Loblied* gesungen hatten, gingen sie hinaus zum Ölberg*.", footnotes: ["s. Anm. zu Mt 26,30", "℘ Lk 22,39; Joh 14,31 ⇨Esyn: Synopse Nr. 367"] },
      { number: 27, text: "*Jesus spricht zu ihnen: Ihr werdet euch alle ärgern*, denn es steht geschrieben: »Ich werde den Hirten schlagen, und die Schafe werden zerstreut werden.«*", heading: "Ankündigung der Verleugnung durch Petrus", footnotes: ["℘ Mt 26,31-35; Lk 22,31-34; Joh 13,36-38", "Das griech. Wort bedeutet auch: Anstoß nehmen, zu Fall kommen, zur Sünde verleitet werden.", "℘ V. 50; Sach 13,7"] },
      { number: 28, text: "Nachdem ich aber auferweckt sein werde, werde ich euch voran nach Galiläa gehen*.", footnotes: ["℘ Kap. 16,7 ⇨Esyn: Synopse Nr. 352"] },
      { number: 29, text: "Petrus aber sprach zu ihm: Wenn sich auch alle ärgern werden*, ich aber nicht.", footnotes: ["Das griech. Wort bedeutet auch: Anstoß nehmen, zu Fall kommen, zur Sünde verleitet werden."] },
      { number: 30, text: "Und Jesus spricht zu ihm: Wahrlich, ich sage dir, dass du heute, in dieser Nacht, ehe der Hahn zweimal kräht, mich dreimal verleugnen wirst*.", footnotes: ["℘ V. 72"] },
      { number: 31, text: "Er aber sprach nachdrücklich: Wenn ich mit dir sterben müsste, werde ich dich nicht verleugnen. Ebenso aber sprachen auch alle." },
      { number: 32, text: "*Und sie kommen an ein Gut* mit Namen Gethsemane, und er spricht zu seinen Jüngern: Setzt euch hier, bis ich gebetet habe*!", heading: "Gethsemane", footnotes: ["℘ Mt 26,36-46; Lk 22,39-46", "o. Grundstück", "℘ Joh 18,1"] },
      { number: 33, text: "Und er nimmt den Petrus und Jakobus und Johannes* mit sich und fing an, sehr bestürzt und geängstigt zu werden*.", footnotes: ["℘ Kap. 5,37; Lk 8,51", "℘ Joh 12,27"] },
      { number: 34, text: "Und er spricht zu ihnen: Meine Seele ist sehr betrübt, bis zum Tod. Bleibt hier und wacht! *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 302"] },
      { number: 35, text: "Und er ging ein wenig weiter und fiel auf die Erde; und er betete, dass, wenn es möglich sei, die Stunde an ihm vorübergehe." },
      { number: 36, text: "Und er sprach: Abba*, Vater*, alles ist dir möglich. Nimm diesen Kelch* von mir weg! Doch nicht, was ich will, sondern was du willst*!", footnotes: ["d. h. Vater (in der aramäischen Muttersprache Jesu)", "℘ Röm 8,15; Gal 4,6", "℘ Kap. 10,38", "℘ Joh 18,11"] },
      { number: 37, text: "Und er kommt und findet sie schlafend, und er spricht zu Petrus: Simon, schläfst du? Konntest du nicht eine Stunde wachen?" },
      { number: 38, text: "Wacht und betet*, damit ihr nicht in Versuchung kommt! Der Geist zwar ist willig, das Fleisch aber schwach*.", footnotes: ["℘ Kap. 13,33", "℘ Röm 7,18"] },
      { number: 39, text: "Und er ging wieder weg, betete und sprach dasselbe Wort." },
      { number: 40, text: "Und als er zurückkam, fand er sie wieder schlafend, denn ihre Augen waren beschwert; und sie wussten nicht, was sie ihm antworten sollten." },
      { number: 41, text: "Und er kommt zum dritten Mal und spricht zu ihnen: So schlaft denn fort und ruht aus! Es ist genug; die Stunde ist gekommen*, siehe, der Sohn des Menschen wird in die Hände der Sünder überliefert*.", footnotes: ["℘ Joh 17,1", "℘ Kap. 10,33"] },
      { number: 42, text: "Steht auf, lasst uns gehen! Siehe, der mich überliefert, ist nahe*.", footnotes: ["℘ Joh 18,3.4"] },
      { number: 43, text: "*Und sogleich, während er noch redet, kommt Judas, einer der Zwölf, heran und mit ihm eine Menge mit Schwertern und Stöcken, von den Hohenpriestern und den Schriftgelehrten und den Ältesten. *", heading: "Gefangennahme", footnotes: ["℘ Mt 26,47-56; Lk 22,47-53; Joh 18,2-12", "℘ ⇨Esyn: Synopse Nr. 331"] },
      { number: 44, text: "Der ihn überlieferte, hatte ihnen aber ein Zeichen gegeben und gesagt: Wen ich küssen werde, der ist es. Den greift, und führt ihn sicher fort!" },
      { number: 45, text: "Und als er kam, trat er sogleich zu ihm und spricht: Rabbi!, und küsste ihn*.", footnotes: ["o. küsste ihn zärtlich\n℘ Ps 55,22"] },
      { number: 46, text: "Sie aber legten ihre Hände an ihn und ergriffen ihn." },
      { number: 47, text: "Einer der Dabeistehenden aber zog das Schwert, schlug den Knecht* des Hohenpriesters und hieb ihm das Ohr ab.", footnotes: ["w. Sklaven"] },
      { number: 48, text: "Und Jesus begann* und sprach zu ihnen: Seid ihr ausgezogen wie gegen einen Räuber mit Schwertern und Stöcken, mich zu fangen?", footnotes: ["w. antwortete; hier in semitisierender Redeweise für den Anfang einer Rede gebraucht"] },
      { number: 49, text: "Täglich war ich bei euch, lehrte im Tempel*, und ihr habt mich nicht ergriffen* — aber damit die Schriften erfüllt werden*!", footnotes: ["℘ Joh 7,14", "℘ Lk 19,47.48", "℘ V. 21"] },
      { number: 50, text: "Und es verließen ihn alle und flohen*.", footnotes: ["℘ V. 27"] },
      { number: 51, text: "Und ein junger Mann, der ein Leinen<hemd> um den bloßen <Leib> geworfen hatte, folgte ihm, und sie ergreifen ihn." },
      { number: 52, text: "Er aber ließ das Leinen<hemd> fahren und floh nackt." },
      { number: 53, text: "*Und sie führten Jesus weg zum Hohenpriester; und alle Hohenpriester und Ältesten und Schriftgelehrten versammeln sich*.", heading: "Vor dem Hohen Rat", footnotes: ["℘ Mt 26,57-68; Lk 22,54.55.63-71; Joh 18,13.14.19-24", "℘ Apg 13,27 ⇨Esyn: Synopse Nr. 332"] },
      { number: 54, text: "Und Petrus folgte ihm von weitem bis hinein in den Hof des Hohenpriesters; und er saß <nun> mit bei den Dienern und wärmte sich am Feuer." },
      { number: 55, text: "Die Hohenpriester aber und der ganze Hohe Rat* suchten Zeugnis gegen Jesus, um ihn zu Tode zu bringen; und sie fanden keins.", footnotes: ["w. Synedrium; der Hohe Rat war, abgesehen vom röm. Statthalter, die höchste Behörde der Juden; vgl. auch Anm. zu Mt 26,59"] },
      { number: 56, text: "Denn viele legten falsches Zeugnis gegen ihn ab, und die Zeugnisse waren nicht übereinstimmend*.", footnotes: ["℘ Ps 27,12"] },
      { number: 57, text: "Und einige standen auf, legten gegen ihn falsches Zeugnis ab* und sprachen:", footnotes: ["℘ Apg 6,13 ⇨Esyn: Synopse Nr. 25"] },
      { number: 58, text: "Wir hörten ihn sagen: Ich werde diesen Tempel, der mit Händen gemacht ist, abbrechen, und in drei Tagen werde ich einen anderen aufbauen, der nicht mit Händen gemacht ist*.", footnotes: ["℘ Kap. 15,29; Mt 27,40"] },
      { number: 59, text: "Und auch so war ihr Zeugnis nicht übereinstimmend." },
      { number: 60, text: "Und der Hohepriester stand auf, <trat> in die Mitte und fragte Jesus und sprach: Antwortest du nichts? Was zeugen diese gegen dich?" },
      { number: 61, text: "Er aber schwieg und antwortete nichts*. Wieder fragte ihn der Hohepriester und spricht zu ihm: Bist du der Christus, der Sohn des Hochgelobten*?", footnotes: ["℘ Kap. 15,5", "℘ Joh 10,24"] },
      { number: 62, text: "Jesus aber sprach: Ich bin es! Und ihr werdet den Sohn des Menschen sitzen sehen zur Rechten der Macht* und kommen mit den Wolken des Himmels*.", footnotes: ["℘ Kap. 12,36", "℘ Kap. 13,26"] },
      { number: 63, text: "Der Hohepriester aber zerriss seine Kleider* und spricht: Was brauchen wir noch Zeugen?", footnotes: ["℘ 3Mo 21,10"] },
      { number: 64, text: "Ihr habt die Lästerung gehört. Was meint ihr? Sie verurteilten ihn aber alle, dass er des Todes schuldig sei*.", footnotes: ["℘ Joh 19,7"] },
      { number: 65, text: "Und einige fingen an, ihn anzuspeien und sein Angesicht zu verhüllen und ihn mit Fäusten zu schlagen und zu ihm zu sagen: Weissage! Und die Diener schlugen ihn ins Gesicht*.", footnotes: ["℘ Kap. 15,19; Mi 4,14"] },
      { number: 66, text: "*Und als Petrus unten im Hof war, kommt eine von den Mägden des Hohenpriesters, *", heading: "Verleugnung durch Petrus", footnotes: ["℘ Mt 26,69-75; Lk 22,56-62; Joh 18,15-18.25-27", "℘ ⇨Esyn: Synopse Nr. 333"] },
      { number: 67, text: "und als sie den Petrus sich wärmen sah, blickte sie ihn an und spricht: Auch du warst mit dem Nazarener Jesus." },
      { number: 68, text: "Er aber leugnete und sprach: Ich weiß nicht, verstehe auch nicht, was du sagst. Und er ging hinaus in den Vorhof.*", footnotes: ["Mehrere alte Handschr. fügen hinzu: Und der Hahn krähte."] },
      { number: 69, text: "Und als die Magd ihn sah, fing sie wieder an, zu den Dabeistehenden zu sagen: Dieser ist einer von ihnen." },
      { number: 70, text: "Er aber leugnete wieder. Und kurz nachher sagten wieder die Dabeistehenden zu Petrus: Wahrhaftig, du bist einer von ihnen, denn du bist auch ein Galiläer." },
      { number: 71, text: "Er aber fing an, sich zu verfluchen und zu schwören: Ich kenne diesen Menschen nicht, von dem ihr redet." },
      { number: 72, text: "Und sogleich krähte zum zweiten Mal der Hahn. Und Petrus gedachte des Wortes, wie Jesus zu ihm gesagt hatte: Ehe der Hahn zweimal kräht, wirst du mich dreimal verleugnen*. Und er begann zu weinen.", footnotes: ["℘ V. 30"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "*Und am frühen Morgen fassten die Hohenpriester mit den Ältesten und Schriftgelehrten und dem ganzen Hohen Rat* sogleich einen Beschluss*, und sie banden Jesus und führten ihn weg und überlieferten ihn dem Pilatus*.", heading: "Anklage vor Pilatus", footnotes: ["℘ Mt 27,1.2.11-14; Lk 22,66-71; 23,1-5; Joh 18,28-38", "w. Synedrium; der Hohe Rat war, abgesehen vom röm. Statthalter, die höchste Behörde der Juden; vgl. auch Anm. zu Mt 26,59", "o. hielten die Hohenpriester . . . eine Beratung ab", "Statthalter des röm. Kaisers in Judäa und Samaria (ca. 26—36 n. Chr.)\n℘ Kap. 10,33; Apg 4,26-28 ⇨Esyn: Synopse Nr. 334"] },
      { number: 2, text: "Und Pilatus fragte ihn: Bist du der König der Juden? Er aber antwortete und spricht zu ihm: Du sagst es*.", footnotes: ["℘ Joh 19,21 ⇨Esyn: Synopse Nr. 336"] },
      { number: 3, text: "Und die Hohenpriester klagten ihn vieler Dinge an. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 337"] },
      { number: 4, text: "Pilatus aber fragte ihn wieder und sprach: Antwortest du nichts? Siehe, wie vieles sie gegen dich vorbringen!" },
      { number: 5, text: "Jesus aber antwortete gar nichts mehr, so dass Pilatus sich wunderte*.", footnotes: ["℘ Kap. 14,61; Joh 19,9"] },
      { number: 6, text: "*Zum Fest aber pflegte er ihnen einen Gefangenen loszugeben, wen sie sich erbaten. *", heading: "Freilassung für Barabbas — Todesurteil für Jesus", footnotes: ["℘ Mt 27,15-26; Lk 23,13-25; Joh 18,39.40; 19,1.16", "℘ ⇨Esyn: Synopse Nr. 339"] },
      { number: 7, text: "Es war aber einer, genannt Barabbas*, mit den Aufrührern gefangen, die in dem Aufstand einen Mord begangen hatten.", footnotes: ["d. h. Sohn des Vaters"] },
      { number: 8, text: "Und die Volksmenge ging hinauf und fing an zu bitten, <dass er tue,> wie er ihnen bisher getan habe." },
      { number: 9, text: "Pilatus aber antwortete ihnen und sprach: Wollt ihr, dass ich euch den König der Juden losgebe?" },
      { number: 10, text: "Denn er wusste, dass die Hohenpriester ihn aus Neid überliefert hatten." },
      { number: 11, text: "Die Hohenpriester aber wiegelten die Volksmenge auf, dass er ihnen lieber den Barabbas losgebe*.", footnotes: ["℘ Apg 3,14"] },
      { number: 12, text: "Pilatus aber antwortete wieder und sprach zu ihnen: Was soll ich denn mit dem tun, den ihr den König der Juden nennt*?", footnotes: ["℘ Joh 19,21"] },
      { number: 13, text: "Sie aber schrien wieder: Kreuzige ihn!" },
      { number: 14, text: "Pilatus aber sprach zu ihnen: Was hat er denn Böses getan*? Sie aber schrien über die Maßen: Kreuzige ihn*!", footnotes: ["℘ Jes 53,9", "℘ Joh 19,6.15; Apg 13,28"] },
      { number: 15, text: "Da aber Pilatus der Volksmenge einen Gefallen tun wollte, gab er ihnen den Barabbas los und überlieferte Jesus, nachdem er ihn hatte geißeln lassen, damit er gekreuzigt werde. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 341"] },
      { number: 16, text: "*Die Soldaten aber führten ihn in den Hof hinein, das ist das Prätorium*; und sie rufen die ganze Schar* zusammen. *", heading: "Verspottung durch die Soldaten", footnotes: ["℘ Mt 27,27-31; Joh 19,2-5", "So hieß der Palast eines Statthalters in den röm. Provinzen.", "Gemeint ist »Kohorte«, eine militärische Einheit der Römer von etwa 600 Mann unter dem Befehl eines Obersten.", "℘ ⇨Esyn: Synopse Nr. 342"] },
      { number: 17, text: "Und sie legen ihm ein Purpurgewand an* und flechten eine Dornenkrone und setzen sie ihm auf;", footnotes: ["℘ Lk 23,11"] },
      { number: 18, text: "und sie fingen an, ihn zu grüßen: Sei gegrüßt, König der Juden!" },
      { number: 19, text: "Und sie schlugen ihn mit einem Rohr auf das Haupt und spien ihn an, und sie beugten die Knie und huldigten ihm*.", footnotes: ["℘ Kap. 14,65"] },
      { number: 20, text: "Und als sie ihn verspottet hatten, zogen sie ihm das Purpurgewand aus und zogen ihm seine Kleider an.*Und sie führen ihn hinaus*, um ihn zu kreuzigen.", heading: "Golgatha", footnotes: ["℘ Mt 27,32-56; Lk 23,26-49; Joh 19,16-30", "℘ Hebr 13,12 ⇨Esyn: Synopse Nr. 343"] },
      { number: 21, text: "Und sie zwingen einen Vorübergehenden, einen gewissen Simon von Kyrene, der vom Feld kam, den Vater Alexanders und Rufus'*, dass er sein Kreuz trage.", footnotes: ["℘ Röm 16,13"] },
      { number: 22, text: "Und sie bringen ihn nach der Stätte Golgatha, was übersetzt ist Schädelstätte. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 344"] },
      { number: 23, text: "Und sie gaben ihm mit Myrrhe* vermischten Wein*; er aber nahm ihn nicht.", footnotes: ["Es ist ein wohlriechendes Harz, wurde für Salben, z.B. zum Einbalsamieren von Toten, für Räucherwerk und als betäubender Zusatz zum Wein verwendet.", "℘ Spr 31,6"] },
      { number: 24, text: "Und sie kreuzigen ihn. Und sie verteilen seine Kleider, indem sie das Los über sie warfen, was jeder bekommen sollte*.", footnotes: ["℘ Ps 22,19"] },
      { number: 25, text: "Es war aber die dritte Stunde*, und sie kreuzigten ihn*.", footnotes: ["In neutestamentl. Zeit teilte man den Tag in 12 Stunden ein, wobei sich die Länge der Stunden nach der Länge des Tages zwischen Sonnenauf- und Sonnenuntergang richtete. Das Ende der 6. Stunde fiel dabei immer auf den Mittag 12 Uhr unserer Zeit.", "℘ Apg 2,36"] },
      { number: 26, text: "Und die Aufschrift seiner Beschuldigung war <oben> angeschrieben: Der König der Juden." },
      { number: 27, text: "Und mit ihm kreuzigen sie zwei Räuber, einen zu seiner Rechten und einen zu seiner Linken. *", footnotes: ["℘ ⇨Esyn: Synopse Nr. 345"] },
      { number: 28, text: "[T>]*", footnotes: ["Andere Handschr. fügen hinzu: Und die Schrift wurde erfüllt, die sagt: »Und er ist unter die Gesetzlosen gerechnet worden.«\n℘ Jes 53,12; Lk 22,37"] },
      { number: 29, text: "Und die Vorübergehenden lästerten ihn, schüttelten ihre Köpfe* und sagten: Ha! Der du den Tempel abbrichst und in drei Tagen aufbaust*,", footnotes: ["℘ Ps 22,8", "℘ Kap. 14,58"] },
      { number: 30, text: "rette dich selbst, und steige herab vom Kreuz!" },
      { number: 31, text: "Ebenso spotteten auch die Hohenpriester mit den Schriftgelehrten untereinander und sprachen: Andere hat er gerettet, sich selbst kann er nicht retten." },
      { number: 32, text: "Der Christus, der König Israels*, steige jetzt herab vom Kreuz, damit wir sehen und glauben! Auch die mit ihm gekreuzigt waren, schmähten ihn*.", footnotes: ["℘ Kap. 14,61", "℘ Ps 69,8.20 ⇨Esyn: Synopse Nr. 346"] },
      { number: 33, text: "Und in der sechsten Stunde* kam eine Finsternis über das ganze Land bis zur neunten Stunde; *", footnotes: ["s. Anm. zu V. 25", "℘ ⇨Esyn: Synopse Nr. 347"] },
      { number: 34, text: "und in der neunten Stunde schrie Jesus mit lauter Stimme: Eloí, Eloí, lemá sabachtháni?, was übersetzt ist: Mein Gott, mein Gott, warum hast du mich verlassen*?", footnotes: ["℘ Ps 22,2"] },
      { number: 35, text: "Und als einige der Dabeistehenden es hörten, sagten sie: Siehe, er ruft Elia." },
      { number: 36, text: "Einer aber lief, füllte einen Schwamm mit Essig, steckte ihn auf ein Rohr, gab ihm zu trinken* und sprach: Halt, lasst uns sehen, ob Elia kommt, ihn herabzunehmen!", footnotes: ["℘ Ps 69,22"] },
      { number: 37, text: "Jesus aber stieß einen lauten Schrei aus und verschied." },
      { number: 38, text: "Und der Vorhang des Tempels zerriss in zwei <Stücke>, von oben bis unten*.", footnotes: ["℘ Hebr 10,20"] },
      { number: 39, text: "Als aber der Hauptmann, der ihm gegenüber dabeistand, sah, dass er so verschied, sprach er: Wahrhaftig, dieser Mensch war Gottes Sohn*!", footnotes: ["℘ Mt 14,33"] },
      { number: 40, text: "Es sahen aber auch Frauen von weitem zu, unter ihnen auch Maria Magdalena* und Maria, Jakobus' des Kleinen und Joses' Mutter, und Salome*,", footnotes: ["d. h. die aus Magdala (Ort am See Genezareth)", "℘ Joh 19,25 ⇨Esyn: Synopse Nr. 348"] },
      { number: 41, text: "die, als er in Galiläa war, ihm nachfolgten und ihm dienten, und viele andere, die mit ihm nach Jerusalem hinaufgekommen waren*.", footnotes: ["℘ Lk 8,2.3"] },
      { number: 42, text: "*Und als es schon Abend geworden war — es war nämlich Rüsttag*, das ist der Vorsabbat* —,", heading: "Grablegung", footnotes: ["℘ Mt 27,57-61; Lk 23,50-56; Joh 19,38-42", "der Wochentag vor einem Sabbat oder Fest, in der Regel ein Freitag", "℘ Mt 27,62 ⇨Esyn: Synopse Nr. 350"] },
      { number: 43, text: "kam Josef von Arimathäa, ein angesehener Ratsherr, der selbst auch das Reich* Gottes erwartete, und er wagte es und ging zu Pilatus hinein und bat um den Leib Jesu*.", footnotes: ["o. die Königsherrschaft", "℘ 5Mo 21,23"] },
      { number: 44, text: "Pilatus aber wunderte sich, dass er schon gestorben sein sollte; und er rief den Hauptmann herbei und fragte ihn, ob er schon lange gestorben sei*.", footnotes: ["℘ Joh 19,33.34"] },
      { number: 45, text: "Und als er es von dem Hauptmann erfuhr, schenkte er Josef den Leib*.", footnotes: ["mit anderen alten Handschr.: Leichnam"] },
      { number: 46, text: "Und der kaufte feines Leinentuch, nahm ihn herab, wickelte ihn in das Leinentuch und legte ihn in eine Gruft, die in einen Felsen gehauen war, und er wälzte einen Stein an die Tür der Gruft." },
      { number: 47, text: "Aber Maria Magdalena* und Maria, die <Mutter> des Joses, sahen zu, wohin er gelegt wurde.", footnotes: ["d. h. die aus Magdala (Ort am See Genezareth)"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "*Und als der Sabbat vergangen war, kauften Maria Magdalena* und Maria, die <Mutter> des Jakobus, und Salome wohlriechende Öle, um hinzugehen und ihn zu salben*.", heading: "Die Frauen am leeren Grab", footnotes: ["℘ Mt 28,1-8; Lk 24,1-12; Joh 20,1-13", "d. h. die aus Magdala (Ort am See Genezareth)", "℘ Lk 23,55.56 ⇨Esyn: Synopse Nr. 352"] },
      { number: 2, text: "Und sie kommen sehr früh am ersten Wochentag zu der Gruft, als die Sonne aufgegangen war*.", footnotes: ["o. als die Sonne eben aufging"] },
      { number: 3, text: "Und sie sprachen zueinander: Wer wird uns den Stein von der Tür der Gruft wegwälzen?" },
      { number: 4, text: "Und als sie aufblickten, sehen sie, dass der Stein zurückgewälzt ist; er war nämlich sehr groß*.", footnotes: ["℘ Mt 27,60"] },
      { number: 5, text: "Und als sie in die Gruft eintraten, sahen sie einen jungen Mann zur Rechten sitzen, bekleidet mit einem weißen Gewand, und sie entsetzten sich." },
      { number: 6, text: "Er aber spricht zu ihnen: Entsetzt euch nicht! Ihr sucht Jesus, den Nazarener, den Gekreuzigten. Er ist auferweckt worden, er ist nicht hier. Siehe da die Stätte, wo sie ihn hingelegt hatten." },
      { number: 7, text: "Aber geht hin, sagt seinen Jüngern und Petrus, dass er euch nach Galiläa vorausgeht! Dort werdet ihr ihn sehen, wie er euch gesagt hat*.", footnotes: ["℘ Kap. 14,28 ⇨Esyn: Synopse Nr. 315"] },
      { number: 8, text: "Und sie gingen hinaus und flohen von der Gruft. Denn Zittern und Bestürzung hatte sie ergriffen, und sie sagten niemand etwas, denn sie fürchteten sich." },
      { number: 9, text: "**Als er aber früh am ersten Wochentag auferstanden war, erschien er zuerst der Maria Magdalena*, von der er sieben Dämonen ausgetrieben hatte*.", heading: "Erscheinungen des Auferstandenen", footnotes: ["℘ Mt 28,9.10.16.17; Lk 24,13-43; Joh 20,13-29; 21,1-23", "Die Verse 9—20 sind in einigen der ältesten Handschr. nicht enthalten.", "d. h. die aus Magdala (Ort am See Genezareth)", "℘ Lk 8,2 ⇨Esyn: Synopse Nr. 363"] },
      { number: 10, text: "Die ging hin und verkündete es denen, die mit ihm gewesen waren und trauerten und weinten*.", footnotes: ["℘ Kap. 2,20"] },
      { number: 11, text: "Und als jene hörten, dass er lebe und von ihr gesehen worden sei, glaubten sie nicht." },
      { number: 12, text: "Danach aber offenbarte er sich zweien von ihnen in anderer Gestalt unterwegs, als sie aufs Land gingen." },
      { number: 13, text: "Und jene gingen hin und verkündeten es den Übrigen; auch jenen glaubten sie nicht." },
      { number: 14, text: "Nachher offenbarte er sich den Elfen selbst*, als sie zu Tisch lagen, und schalt ihren Unglauben und ihre Herzenshärtigkeit, dass sie denen, die ihn auferweckt gesehen, nicht geglaubt hatten*.", footnotes: ["℘ 1Kor 15,5", "℘ Lk 9,41"] },
      { number: 15, text: "*Und er sprach zu ihnen: Geht hin in die ganze Welt und predigt das Evangelium der ganzen Schöpfung*!", heading: "Aussendung der Jünger — Himmelfahrt Jesu", footnotes: ["℘ Mt 28,18-20; Lk 24,44-53", "℘ Kap. 13,10; Apg 10,42; Kol 1,23"] },
      { number: 16, text: "Wer gläubig geworden und getauft worden ist, wird gerettet werden*; wer aber ungläubig ist, wird verdammt werden*.", footnotes: ["℘ Apg 2,38; 16,31.33; Röm 1,16; 10,9; 1Petr 3,21", "℘ Joh 3,36"] },
      { number: 17, text: "Diese Zeichen aber werden denen folgen, die glauben: In meinem Namen werden sie Dämonen austreiben*; sie werden in neuen Sprachen* reden*;", footnotes: ["℘ Apg 5,16", "o. Zungen", "℘ Apg 2,4"] },
      { number: 18, text: "werden Schlangen aufheben, und wenn sie etwas Tödliches trinken, wird es ihnen nicht schaden*; Schwachen werden sie die Hände auflegen, und sie werden sich wohl befinden*.", footnotes: ["℘ Lk 10,19; Apg 28,3-6", "℘ Mt 10,8; Apg 5,15.16"] },
      { number: 19, text: "Der Herr wurde nun, nachdem er mit ihnen geredet hatte, in den Himmel aufgenommen* und setzte sich zur Rechten Gottes*.", footnotes: ["℘ 2Kö 2,11; Apg 1,9", "℘ Kap. 12,36; Ps 110,1; Mt 26,64; Röm 8,34; Eph 1,20; Kol 3,1; Hebr 1,3; 1Petr 3,22"] },
      { number: 20, text: "Jene aber zogen aus und predigten überall, während der Herr mitwirkte und das Wort durch die darauf folgenden Zeichen bestätigte*.*", footnotes: ["℘ Lk 9,6; Apg 2,43; Hebr 2,3.4", "Die Verse 9—20 sind in einigen der ältesten Handschr. nicht enthalten."] },
    ]},
  ]
};
